          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"818b4630-c5d5-5be6-be25-8ec52e1b23c9","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -شرب املسكر -تعاطي احلشيش املخدر -قيادة السيارة حتت تأثير املسكر إقرار -حد املسكر -التعزير باملنع من السفر .","document_number":"34270925","case_number":"34213894","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/17","year":"1434","subject":"مخدرات -تعاطي مخدرات -شرب املسكر -تعاطي احلشيش املخدر -قيادة السيارة حتت تأثير املسكر إقرار -حد املسكر -التعزير باملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34270925 :‬تاريخه ‪1434/07/17 :‬هـ‬\n                    ‫رقم الدعوى‪34213894 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n    ‫‪               34322429‬تاريخه‪1434/9/20:‬هـ‬\n\n\n\n‫مخدرات ‪ -‬تعاطي مخدرات ‪ُ -‬شــرب املســكر ‪ -‬تعاطي احلشــيش املُخدر‬\n‫‪ -‬قيــادة الســيارة حتــت تأثيــر املُســكر ــإقرار ‪ -‬حــد املســكر ‪ -‬التعزيــر‬\n                                                          ‫باملنــع مــن الســفر ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه صلــى اهلل عليــه وســلم « مــن شــرب اخلمــر فــا جلــدوه »‪ .‬أخرجه‬\n                                               ‫أحمد وأبو داود والنســائي ‪.‬‬\n‫‪ -2‬فعــل عمــر ـ رضــي اهلل عنــه ـ مبحضــر املهاجريــن واألنصــار بجلــد‬\n                                                 ‫الســكران ثمانــن جلــدة ‪.‬‬\n                                                   ‫‪ -3‬املرء مؤاخذ بإقراره ‪.‬‬\n‫‪ -4‬قــال ابــن حجــر يف فتــح البــاري (‪ « : )45/10‬واســتدل مبطلــق قولــه‬\n‫صلــى اهلل عليــه وســلم « كل ُمســكر حــرام » علــى حتــرمي مــا ُيســكر ولــو‬\n‫لــم يكــن شــراب ًا فيدخــل يف ذلــك احلشيشــة وغيرهــا وقــد جــزم النــووي‬\n                                                     ‫وغيــره بأنهــا ُمســكرة » ‪.‬‬\n‫‪ -5‬مــا ذكــره أهــل العلــم ( مــن أنــه إذا اجتمعــت حــدود مــن جنــس‬\n‫واحــد قبــل إقامــة احلــد تداخلــت وكفــاه حــد واحــد ) كشــاف القنــاع‬\n                                                                      ‫(‪.)29/14‬‬\n‫‪ -6‬املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الفقــرة‬\n                                                                            ‫(‪.)1‬‬\n             ‫‪ -7‬املادة (‪ )3‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                                                                                    ‫‪128‬‬\n\f                    ‫‪ -8‬القاعدة القانونية (ال عقوبة وال جرمية إ َّال بنص ) ‪.‬‬\n      ‫‪ -9‬املــادة (‪ )30‬مــن الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة والتــي جعلــت للقاضــي ســلطة تقديريــة لســجن‬\n                                                                 ‫املتعاطــي ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب ا ُملســكر وتعاطــي‬\n      ‫احلشــيش وقيــادة الســيارة حتــت تأثيــر ا ُملســكر ومــادة احلشــيش و طلــب‬\n      ‫املدعــي العــام احلكــم عليــه بحد املســكر ‪ ،‬وســجن املدعــى عليه ومنعه‬\n      ‫مــن الســفر بنــاء علــى املــواد (  ‪ ) 56/ 41‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثرات العقلية ‪ ،‬حيث أنه مت القبض على املدعى عليه إثر ممارســة‬\n      ‫التفحيــط وبعثــت عينــة مــن ســوائله أثبــت التقريــر الكيمائــي إيجابيــة‬\n      ‫العينــة ملركبــات احلشــيش املخــدرة والكحول‪،‬كمــا أقــر املدعــى‬\n      ‫عليــه بشــربه ا ُملســكر وتعاطيــه احلشــيش وأنكــر قيــادة الســيارة حتــت‬\n      ‫تأثيــر ا ُملســكر واحلشــيش ‪ ،‬وبنــاء علــى ماتقــدم حكمــت احملكمــة‬\n      ‫علــى املدعــى عليــه بحــد ا ُملســكر ‪ -‬منعــه مــن الســفر ملــدة ســنتني خــارج‬\n      ‫اململكــة وصــرف النظــر عــن تطبيــق املــادة (‪ )41‬مــن نظــام املخــدرات‬\n      ‫واملؤثــرات العقليــة ‪،‬حيــث أنــه لــم يثبــت لــدى احملكمــة قيــادة املدعــى‬\n      ‫عليــه الســيارة حتــت تأثيــر ا ُملســكر واحلشــيش وقنــع املدعــى عليــه‬\n      ‫باحلكــم وأبــدى املدعــي العــام اعتراضــه علــى احلكــم بــدون الئحــة‬\n                        ‫اعتراضيــة وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪129‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق  ‪1434/ 7 /17‬ه ـ لــدي‬\n‫أنــا القاضــي باحملكمــة اجلزائيــة بالدمــام وبنــاء علــى املعاملــة احملالــة‬\n‫إلينــا مــن رئيــس احملكمــة برقــم (‪ )....‬وتاريــخ ‪1434/ 5 /8‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر‪ .......... /‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫رقــم (‪ ).......‬وقــدم املدعــي العــام الئحــة اإلدعــاء املتضمنــة بصفتي مدعي ًا‬\n‫عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة باملنطقــة الشــرقية أدعــي علــى‬\n‫املذكــور أعــاه باالطــاع علــى خطــاب مديــر مــرور الدمــام رقــم (‪).......‬‬\n‫وتاريــخ ‪ 1434/3/18‬املتضمــن انــه بيــوم اجلمعــة املوافــق ‪1434/2/22‬ه ـ‬\n‫ويف متــام الســاعة (‪ )4:15‬ص ‪ ،‬وقــع حــادث صــدم (عولــج مــن قبــل جهــة‬\n‫االختصــاص) بحــي بــن ســيارة مــن نــوع ‪ .......‬حتمــل الرقــم (‪)..........‬‬\n‫بقيــادة املتهــم ‪ /‬وبــن جســم ثابــت عبــارة عــن عمــود تابــع لشــركة‬\n‫االتصــاالت وذلــك بســبب ممارســة املتهــم ( للتفحيــط ) وببعــث عينــة مــن‬\n‫ســوائله ( الــدم والبــول ) ورد تقريــر املركــز اإلقليمــي ملراقبــة الســموم‬\n‫الشــرعية رقــم (‪ )..........‬وتاريــخ ‪1434/2/25‬ه ـ متضمنــا ايجابيــة‬\n‫العينــات املأخــوذة منــه ملركبــات احلشــيش املخــدر املــدرج باجلــدول األول‬\n‫فئــة ( أ ) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وايجابيتــه‬\n‫ملــادة الكحــول االيثيلــي وبنــاء علــى التقريــر الكيمــاوي مت القبــض‬\n‫عليــه بتاريخ‪1434/3/18‬ه ـ بســماع أقــوال املتهــم األوليــة مــن قبــل شــعبة‬\n‫مكافحــة املخــدرات بالدمــام أقــر بشــربه للمســكر وبتعاطيــه ملــادة‬\n‫احلشــيش املخــدر وانــه يتعاطــى احلشــيش منــذ أربعــة أشــهر وأخــر مــرة‬\n‫تعاطــى فيهــا كانــت قبــل احلــادث بأربعــة  أســابيع قــد انتهــى التحقيــق‬\n\n                                                                                       ‫‪130‬‬\n\f      ‫إلــى اتهــام‪ ........../‬باالتــي‪-1 :‬شــرب املســكر ‪-2‬تعاطيــه للحشــيش‬\n      ‫‪-3‬قيــادة الســيارة حتــت تأثيــر املســكر ومــادة احلشــيش وذلــك لألدلــة‬\n      ‫والقرائــن التاليــة ‪ -1 :‬اعترافــه مبــا نــوه عنــه املــدون علــى الصفحــة رقــم‬\n      ‫(‪ )2‬مــن ملــف التحقيــق املرفــق علــى اللفــة رقــم (‪ -2 )1‬تقريــر املركــز‬\n      ‫اإلقليمــي ملراقبــة الســموم الشــرعية املنــوه عنــه واملرفــق علــى اللفــة‬\n      ‫رقــم (‪ )2‬وحيــث إن مــا أقــدم عليــه املتهــم املذكــور ‪ -‬وهــو بكامــل‬\n      ‫أهليتــه املعتبــرة شــرعا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا‬\n      ‫أطلــب اآلتــي‪ :‬أوال‪ :‬احلكــم عليــه بحــد الســكر لقــاء شــربه للمســكر‬\n      ‫ثانيــا‪ :‬إثبــات مــا أســند إليــه مــن تعاطــي احلشــيش املخــدر وفق ـ ًا للفقــرة‬\n      ‫رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة ووفــق املــادة (‪ )30‬مــن الالئحــة التنفيذيــة واحلكــم عليــه مبــا‬\n      ‫يلــي‪ -1 :‬بعقوبــة الســجن الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪)41‬‬\n      ‫مــن النظــام ‪ -2‬منعــه مــن الســفر وفق ـ ًا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n      ‫(‪ )56‬مــن النظــام ثالثــا‪ :‬إثبــات قيادتــه للســيارة حتــت تأثيــر املســكر‬\n      ‫واحلشــيش املخــدر وفقــا للفقــرة رقــم (‪ )8‬مــن اجلــدول رقــم (‪ )1‬امللحــق‬\n      ‫بنظــام املــرور وإفهامــه أن عقوبتــه الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n      ‫رقــم (‪ )68‬مــن نظــام املــرور تقــرر مــن اجلهــة املختصــة وفــق الفقــرة (‪)2‬‬\n      ‫مــن قــرار مجلــس الــوزراء رقــم (‪ )315‬يف ‪1429/10/24‬هــ  وبــاهلل‬\n      ‫التوفيــق وبســؤال املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام‬\n      ‫مــن شــرب املســكر وتعاطــي احلشــيش املخــدر فهــذا صحيــح أمــا مــا‬\n      ‫ذكــره مــن قيــادة الســيارة حتــت تأثيرهمــا فهــذا غيــر صحيــح  ألننــي لــم‬\n      ‫أكــن أقــود الســيارة حــن وقــوع احلــادث وإمنــا كنــت راكبـ ًا يف الســيارة‬\n      ‫والــذي كان يقودهــا أحــد زمالئــي هــذه إجابتــي وبعــد تدويــن مــا ســبق‬\n\n\n‫‪131‬‬\n\f‫جــرى االطــاع علــى جميــع أوراق املعاملــة ومنهــا أقــوال املدعــى عليــه‬\n‫املدونــة علــى الصفحــة الثانيــة مــن ملــف التحقيــق فوجــدت فيهــا اعترافـ ًا‬\n‫مــن املدعــى عليــه بشــرب املســكر وتعاطــي احلشــيش املخــدر ولكــن لــم‬\n‫أجــد فيهــا اعترافـ ًا بقيــادة الســيارة حتــت تأثيرهمــا كمــا جــرى االطالع‬\n‫علــى خطــاب مديــر مــرور الدمــام املوجــه إلــى مديــر إدارة مكافحــة‬\n‫املخــدرات بالدمــام برقــم (‪ )......‬وتاريــخ ‪1434/3/18‬ه ـ املتضمــن أن‬\n‫الســيارة حــن وقــوع احلــادث كانــت بقيــادة املدعــى عليــه وجــرى البحــث‬\n‫يف املعاملــة عــن أي أوراق تخــص احلــادث وكيفيــة وقوعــه واألشــخاص‬\n‫املتواجديــن يف الســيارة حينــذاك فلــم أجــد شــيئ ًا مــن ذلــك كمــا أنــه ال‬\n‫يوجــد حتقيــق مــع املدعــى عليــه يف هيئــة التحقيــق واالدعــاء العــام  ولــم‬\n‫أجــد أي جهــد مبــذول مــن احملقــق للتأكــد مــن صحــة مــا يدعيــه املدعــى‬\n‫عليــه مــن أنــه لــم يكــن يقــود الســيارة حتــت تأثيــر املســكر واحلشــيش‬\n                                                              ‫املخــدر مــن عدمــه‬\n‫ولــم أجــد أي حتقيــق مــع املواطــن للتأكــد مــن صحــة ادعــاء املدعــى‬\n‫عليــه ثــم جــرى االطــاع علــى صحيفــة الســوابق املرفقــة باملعاملــة‬\n‫واملتضمنــة عــدم وجــود ســوابق مســجلة املدعــى عليــه فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه بشــرب املســكر‬\n‫وتعاطــي احلشــيش املخــدر واملــرء مؤاخــذ بإقــراره ولقولــه صلــى اهلل عليــه‬\n‫وســلم»من شــرب اخلمــر فاجلدوه»أخرجــه أحمــد وأبــو داود والنســائي‬\n‫وألن عمر‪-‬رضــي اهلل عنه‪-‬جلــد يف حــد اخلمــر ثمانــن جلــدة وكان‬\n‫ذلــك مبحضــر مــن املهاجريــن واألنصار‪-‬رضــي اهلل عنهم‪-‬فلــم ينكــره‬\n‫أحــد منهــم وبنــاء علــى مانــص عليــه أهــل العلــم مــن إقامــة حــد املســكر‬\n‫علــى متنــاول احلشــيش قــال ابــن حجــر يف فتــح الباري(‪ »)45/10‬و ُأســتدل‬\n\n\n                                                                                     ‫‪132‬‬\n\f       ‫مبطلــق قولــه صلــى اهلل عليــه وســلم «كل مســكر حــرام» علــى حتــرمي‬\n       ‫مايســكر ولــو لــم يكــن شــراب ًا فيدخــل يف ذلــك احلشيشــة وغيرهــا وقــد‬\n       ‫جــزم النــووي وغيــره بأنهــا مســكرة» وبنــاء علــى مانــص عليــه أهــل العلــم‬\n       ‫مــن أنــه إذا اجتمعــت حــدود مــن جنــس واحــد قبــل إقامــة احلــد تداخلــت‬\n       ‫وكفــاه حــد واحــد (كشــاف القنــاع‪ )29/14‬واســتناد ًا للفقــرة الثانيــة‬\n       ‫مــن املــادة الثالثــة والفقــرة األولــى من املادة السادســة واخلمســن من نظام‬\n       ‫مكافحــة املخــدرات واملؤثــرات العقليــة وحيــث إنــه العقوبــة والجرميــة‬\n       ‫إال بنــص وحيــث إن العقوبــات الــواردة يف املــادة احلاديــة واألربعــن‬\n       ‫مــن نظــام مكافحــة املخــدرات ال تنطبــق علــى التعاطــي واالســتعمال‬\n       ‫بخــاف العقوبــة الــواردة يف املــادة السادســة واخلمســن مــن نفــس النظــام‬\n       ‫فتنطبــق عليــه وحيــث أن املــادة الثالثــن مــن الالئحــة التنفيذيــة لنظــام‬\n       ‫مكافحــة املخــدرات واملؤثــرات العقليــة والتــي تنــص علــى مايلــي إذا‬\n       ‫رأى القاضــي تعزيــر املتعاطــي أو املســتعمل للمــواد املخــدرة أو املؤثــرات‬\n       ‫العقليــة بالســجن‪ ،‬فــا تتجــاوز العقوبــة احلــد األعلــى املنصــوص عليهــا‬\n       ‫يف الفقــرة (‪ )1‬مــن املــادة (احلاديــة واألربعــن) قــد تركــت موضوع ســجن‬\n       ‫املتعاطــي للمخــدرات مســألة اختياريــة وســلطة تقديريــة للقاضــي وحيــث‬\n       ‫إنــه التوجــد ســوابق مســجلة علــى املدعــى عليــه وحيــث إنــه يوجــد نقــص‬\n       ‫يف التحقيــق وال توجــد أدلــة كافيــة تثبــت قيــام املدعــى عليــه بقيــادة‬\n       ‫الســيارة حتــت تأثيــر املســكر واحلشــيش املخدر والحتمــال صحة مادفع‬\n      ‫بــه املدعــى عليــه مــن كــون أحد زمالئه هو من كان يقود الســيارة حني ‬\n       ‫وقــوع احلــادث لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه بشــرب املســكر‬\n       ‫وتعاطــي احلشــيش املخــدر وحكمــت عليــه لقــاء ذلــك مبــا يلــي ‪ /1‬جلــده‬\n       ‫حــد املســكر ثمانــن جلــدة ‪ /2‬منعــه مــن الســفر خــارج اململكــة مــدة‬\n\n\n‫‪133‬‬\n\f‫ســنتني تبــدأ مــن حــن اكتســاب احلكــم للقطعيــة‪ /3‬صرفــت النظــر‬\n‫عــن طلــب املدعــي العــام إيقــاع العقوبــة املنصــوص عليهــا يف املــادة احلاديــة‬\n‫واألربعــن مــن نظــام مكافحــة املخــدرات علــى املدعــى عليه‪/4‬لــم يثبــت‬\n‫لــدي إدانــة املدعــى عليــه قيــادة الســيارة حتــت تأثيــر املســكر واحلشــيش‬\n‫املخــدر لعــدم كفايــة األدلــة وبعــرض احلكــم علــى املدعــى عليــه قــرر‬\n‫القناعــة بــه وقــرر املدعــي العــام االعتــراض بالئحــة فأجيــب لطلبــه ومت‬\n‫تســليمه نســخة مــن احلكــم وأفهــم بتقــدمي االعتــراض عليــه خــال مهلــة‬\n‫ثالثــن يومــا وأنــه إذا انتهــت هــذه املهلــة ولــم يتقــدم باعتراضــه ســقط‬\n‫حقــه يف ذلــك وســوف يتــم رفــع احلكــم إلــى محكمــة االســتئناف بــدون‬\n‫الئحــة اعتراضيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وبــه‬\n                                                        ‫حــرر يف ‪1434/7/17‬هــ‪.‬‬\n‫ويف يــوم الثالثــاء املوافــق ‪1434/11/4‬ه ـ افتتحــت اجللســة الســاعة‬\n‫الواحــدة وقــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم (‪)..........‬‬\n‫وتاريــخ ‪1434/10/28‬هــ  املتعلقــة بدعــوى املدعــي العــام ضــد ‪........../‬‬\n‫وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم (‪)..........‬‬\n‫وتاريــخ ‪1434/9/20‬ه ـ املتضمــن املصادقــة علــى احلكــم لــذا جــرى‬\n‫إحلــاق ذلــك حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                   ‫وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n\n\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫املقيــدة لــدى احملكمــة برقــم وتاريــخ ‪1434/09/10‬ه ـ الــواردة مــن‬\n‫فضيلــة‪ ........../‬رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم  وتاريــخ‬\n\n\n                                                                                         ‫‪134‬‬\n\f      ‫‪1434/08/28‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪ ........../‬املســجل برقــم وتاريــخ ‪1434/07/17‬ه ـ‬\n      ‫اخلــاص بدعوى‪/‬املدعــي العــام   ضــد‪ /‬يف قضيــة مخــدرات   وقــد‬\n      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه  وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n      ‫‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                             ‫يف‪1434/09/17‬هــ‪.‬‬\n\n\n\n\n‫‪135‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":128,"source_page_end":135,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1853860ba4e1da4c0f53189acdb1791c99526c5233e5785f8ba8e2c9dbf27d79","normalized_text_hash":"255a9b624fb15757d72375623c4ac2d01eba5f19505c12f0811562740b34e1c3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p128-34270925"},{"id":"f5663bcd-4deb-5611-aed8-1ec8028cc600","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -التعدي على رجل أمن -ابتاع حبوب محظورة -التعزير بالسجن واجللد واملنع من السفر -1املادة ( )41من نظام مكافحة املخدرات واملؤثرات العقلية .","document_number":"34234754","case_number":"34227885","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/07","year":"1434","subject":"مخدرات -تعاطي مخدرات -التعدي على رجل أمن -ابتاع حبوب محظورة -التعزير بالسجن واجللد واملنع من السفر -1املادة ( )41من نظام مكافحة املخدرات واملؤثرات العقلية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34234754 :‬تاريخه‪1434/06/07 :‬هـ‬\n                    ‫رقم الدعوى‪34227885 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪     34281893‬تاريخه‪1434/7/29 :‬هـ‬\n\n\n\n‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬التعــدي علــى رجــل أمــن ‪ -‬ابتــاع حبــوب‬\n                ‫محظــورة ‪ -‬التعزيــر بالســجن واجللــد واملنــع من الســفر‬\n\n\n\n\n          ‫‪ -1‬املادة (‪ )41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n          ‫‪ -2‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بابتــاع احلبــوب احملظــورة ‪،‬‬\n  ‫ومقاومــة رجــال األمــن وطلــب املدعــي العــام ســجن املدعــى عليــه ومنعــه‬\n  ‫مــن الســفر بنــاء علــى املــواد (‪ )41‬و (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n  ‫واملؤثــرات العقليــة لقــاء ابتــاع احلبــوب املخــدرة وتعزيــره لقــاء التعــدي‬\n‫علــى رجــل االمــن‪ ،‬حيــث أنــه أثنــاء قيــام فرقــة مكافحــة املخــدرات  ‬\n  ‫بعملهــا شــوهدت ســيارة بقيــادة  املدعــى عليــه  ‪ ،‬لوحــظ عليــه عالمــات‬\n  ‫اخلــوف و اإلرتبــاك ‪ ،‬فتــم القبــض عليــه ‪ ،‬فقــام بدفــع رجــل األمــن وقــام‬\n  ‫بابتــاع شــي مــا بســرعة يشــتبه أن يكــون مــن احلبــوب احملظــورة ‪،‬‬\n  ‫وبتفتيشــه ‪ ،‬وبتفتيــش الســيارة لــم يعثــر علــى شــي  ‪  ،‬وبتحليــل عينــة‬\n  ‫املدعــى عليــه تبــن احتوائهــا علــى مــادة اإلمفيتامــن ‪ ،‬أنكــر املدعــى‬\n  ‫ا وطلــب القاضــي مــن املدعــي‬   ‫عليــه مــا جــاء يف الدعــوى جملــة وتفصيـ ً‬\n\n                                                                                      ‫‪136‬‬\n\f        ‫العــام إحضــار بينتــه ‪ ،‬وقــد شــهد الشــهود بــأن املدعــى عليــه قــام بابتــاع‬\n        ‫شــيء كان معــه يشــتبه أن تكــون مــن احلبــوب احملظــورة ‪ ،‬وقــد عدلــت‬\n        ‫البينــة حســب األصــول الشــرعية ووبنــاء علــى ماتقــدم فقــد حكمــت‬\n      ‫احملكمــة بجلــد املدعــى عليــه تعزيــر ًا لقــاء مقاومتــه لرجــال األمــن ‪  ،‬‬\n        ‫وتكــرار ســوابقه ‪  ،‬وابتالعــه للحبــوب احملظــورة و لــم يقتنــع املدعــي‬\n        ‫العــام باحلكــم وطلــب اســتئنافه بــدون الئحــة ‪ ،‬وأمــا املدعــى عليــه فقــد‬\n        ‫اعتــرض بالئحــة اعتراضيــه وصــدق احلكــم مــن محكمــة االســتئناف  ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا   القاضــي يف احملكمــة العامــة بعرعـر   ‬\n         ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بعرعــر برقــم  وتاريــخ ‪ 1434/05/18‬هــ  املقيــدة باحملكمــة برق ـم  ‬\n         ‫وتاريــخ ‪ 1434/05/18‬هــ  ففــي يــوم  الثالثــاء املوافــق‪1434/05/21‬‬\n         ‫ه ـ افتتحــت اجللســة الســاعة ‪   11 : 15‬وفيهــا حضــر املدعــي العــام‬\n         ‫وادعــى قائــا  ‪ :‬بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة‬\n         ‫مبنطقــة احلــدود الشــمالية أدعــي علــى ‪ /‬ســعودي اجلنســية مبوجــب‬\n         ‫الســجل املدنــي رقــم  فأنــه بتاريخ‪1434/3/27‬هــ  وأثنــاء قيــام فرقــة‬\n         ‫مكافحــة املخــدرات بعملهــا املعتــاد وذلــك مبســح األماكــن املشــبوهة‬\n         ‫مــن مروجــي ومســتخدمي املخــدرات‪  ،‬وعنــد الســاعة الثانيــة عشــر‬\n         ‫والربــع (‪ )12,15‬لي ـاً   شــوهدت ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة‬\n         ‫رقــم (‪ )..........‬متوقفــه عنــد احــد األماكــن املشــبوهة يف حــي العزيزيــة‬\n         ‫ويوجــد بهــا احــد األشــخاص وكانــت الســيارة مطفــأه و لوحــظ علــى‬\n         ‫الشــخص الــذي بدخلهــا اخلــوف واالرتبــاك فتــم القبــض عليــه وإنزالــه‬\n\n‫‪137‬‬\n\f  ‫مــن الســيارة ‪ ،‬فقــام املتهــم بدفــع رجــل األمــن وقــام بابتــاع شــيء مــا‬\n  ‫بســرعه يشــتبه أن يكــون مــن احلبــوب احملظــورة‪ ،‬وبتفتيشــه وتفتيــش‬\n  ‫ســيارته لــم يعثــر علــى أي شــيء مــن املمنوعــات  ‪  ،‬وبنــا علــى مــا قــام بــه‬\n  ‫مت اصطحــاب املتهــم إلدارة مكافحــة املخــدرات ومت إيداعــه التوقيــف‬\n  ‫يف حينــه  وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز‬\n‫الســموم بتبــوك رقــم لعــام ‪1434‬ه ـ إيجابيــة عينــة بول املتهــم لالمفيتامني ‬\n  ‫املنبــه للجهــاز العصبــي وهــو مــن املؤثــرات العقليــة اخلاضعــة للرقابــة‬\n  ‫واملنــوه عنــه باجلــدول الثانــي فئــة (ب) يف تعميــم صاحــب الســمو امللكــي‬\n‫وزيــر الداخليــة رقــم وتاريخ‪1426/10/25‬هــ‪ .‬وقــد انتهــى التحقيــق إلــى  ‬\n  ‫اتهــام‪ ، /‬بابتــاع احلبــوب احملضــوره احملتويــة علــى مــادة اإلمفيتامــن‬\n  ‫املنبهــة للجهــاز العصبــي ‪،‬املجــرم نظامــا بنــص املــادة الثالثــة مــن نظــام‬\n  ‫مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬الصــادر باملرســوم امللكــي‬\n  ‫رقــم  وتاريــخ ‪1426/7/8‬هــ‪ ،‬وقيامــه بدفــع رجــال األمــن ‪.‬وذلــك لألدلــة‬\n  ‫والقرائــن التاليــة ‪ -1 :‬مــا جــاء مبحضــر القبــض املرفــق املــدون علــى‬\n  ‫الصفحــة رقــم (‪) 13,12‬لفــة رقــم (‪ -2.)1‬مــا جــاء بالتقريــر الكيميائــي‬\n  ‫الشــرعي املرفــق لفــة رقــم (‪ .)27‬وحيــث أن مــا أقــدم عليــه املتهــم وهــو‬\n  ‫بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرعا‬\n  ‫ومجــرم نظامــا بنــص املــادة الثالثــة مــن نظــام مكافحــة املخــدرات‬\n  ‫واملؤثــرات العقليــة ‪ ،‬الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ‬\n  ‫‪1426/7/8‬ه ـ لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n                                                                             ‫مبــا يلــي‪:‬‬\n  ‫‪-1‬عقوبــة الســجن وفقــا للفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n  ‫مكافحــة املخــدرات واملؤثــرات العقليــة واملــادة (‪ )30‬مــن الئحتــه‬\n\n\n                                                                                            ‫‪138‬‬\n\f      ‫التنفيذية‪-2.‬عقوبــة املنــع مــن الســفر خــارج اململكــة وفقا للفقــرة األولى‬\n      ‫مــن املــادة (‪ )56‬مــن النظــام نفســه ‪ -3‬عقوبــة تعزيريــة لقــاء قيامــه بدفــع‬\n      ‫رجــل األمــن وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه احلاضــر‬\n      ‫انكــر مــا جــاء بهــا جملــة وتفصيــا وبســؤال املدعــي العــام البينــة‬\n      ‫علــى الدعــوى فأجــاب قائــا‪ :‬بينتــي ماجــاء مبحضــر القبــض املرفــق‬\n      ‫لكــم ومــن اعــده شــهود عليــه واطلــب مهلــة الحضارهــم ولتمكــن‬\n      ‫املدعــي العــام مــن ذلــك جــرى رفــع اجللســة وعليــه حصــل التوقيــع‪ .‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫حــرر يف  ‪ 1434/05/21‬ه ـ احلمــد هلل وحــده وبعــد  ففــي يــوم  اإلثنــن‬\n      ‫املوافــق‪ 1434/05/27‬ه ـ افتتحــت اجللســة الســاعة  ‪ 10.45‬وفيهــا حضر‬\n      ‫املدعــي العــام وحضــر حلضــوره املدعــى عليــه املثبــت هويتهمــا ســابقا وقد‬\n      ‫احضــر املدعــي العــام لشــهاده كال مــن  ســجل مدنــي رقــم  وقــد قــال‬\n      ‫معرفــا اننــي اعمــل مبكافحــة املخــدرات بعرعــر برتبــة جنــدي وابلــغ مــن‬\n      ‫العمــر (‪ )29‬عــام واســكن مبدينــة عرعــر وليــس لــي معرفــه باملدعــى‬\n      ‫عليــه و ســجل مدنــي رقــم  وقــد قــال معرفــا اننــي اعمــل مبكافحــة‬\n      ‫املخــدرات بعرعــر برتبــة جنــدي وابلــغ مــن العمــر (‪ )22‬عــام واســكن‬\n      ‫مبدينــة عرعــر وليــس لــي معرفــه باملدعــى عليــه ولــدى استشــهادهما‬\n      ‫شــهد كل واحــد منهمــا مبفــرده فأنــه بتاريــخ ‪1434/3/27‬هــ  وأثنــاء‬\n      ‫قيامنــا بعملنــا املعتــاد وذلــك مبســح األماكــن املشــبوهة مــن مروجــي‬\n      ‫ومســتخدمي املخــدرات‪  ،‬وعنــد الســاعه الثانيــة عشــر والربــع (‪)12,15‬‬\n      ‫لي ـاً  شــاهدنا ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم () متوقفــه عنــد‬\n      ‫احــد االماكــن املشــبوهه يف حــي العزيزيــة ويوجــد بهــا أحــد األشــخاص‬\n      ‫وكانــت الســيارة مطفــأه و لوحــظ علــى الشــخص الــذي بدخلهــا اخلــوف‬\n\n\n‫‪139‬‬\n\f ‫واإلرتبــاك فتــم القبــض عليــه وإنزالــه مــن الســيارة وهــو ذات الشــخص‬\n ‫املاثــل امامنــا  فقــام املتهــم بدفعنــا وقــام ببتــاع شــيء مــا بســرعة يشــتبه‬\n ‫أن يكــون مــن احلبــوب احملظــورة‪ ،‬وبتفتيشــه وتفتيــش ســيارته لــم يعثــر‬\n ‫علــى أي شــيء مــن املمنوعــات ‪  ،‬وبنــا علــى مــا قــام بــه مت إصطحــاب‬\n ‫املتهــم الدارة مكافحــة املخــدرات وقــد قــاوم ورفــض الركــوب يف‬\n ‫الدوريــة هكــذا شــهدا وبعــرض ذلــك علــى املدعــى عليــه أصــر علــى‬\n ‫إنــكاره وبســؤاله هــل لديــه طعــن بالشــهود أجــاب قائــا ال اعــرف احــد‬\n ‫منهــم وقــد جــرى تعديــل الشــهود مــن كال مــن و ولتأمــل ماجــرى ضبطــه‬\n ‫جــرى رفــع اجللســة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/05/27‬ه ـ‬\n ‫احلمــد هلل وحــده وبعــد  ففــي يــوم  األربعــاء املوافــق‪ 1434/06/07‬ه ـ‬\n ‫افتتحــت اجللســة الســاعة ‪ 11.30‬وفيهــا حضــر املدعــي العــام وحضــر‬\n ‫حلضــوره املدعــى عليــه واملثبــت هويتهــم ســابقا وبســؤال املدعــي‬\n ‫العــام هــل لديــه مزيــد بينــة أجــاب قائ ـاً‪ :‬ليــس لــدي ســوى ماقدمتــه‬\n ‫وقــد جــرى منــا االطــاع علــى التقريــر الكيميائــي رقــم (‪ )....‬وتاريــخ‬\n ‫‪1434/4/28‬ه ـ ونــص احلاجــة منــه ( وبإجــراء الفحــص الكميائــي‬\n ‫الشــرعي ثبــت إجابيــة عينــة البــول لإلمفيتامــن ) أ‪.‬ه ـ وذلــك علــى لفــه‬\n‫رقــم (‪ )27‬مــن طيــات املعاملــه وبســؤال املدعــى عليــه عــن الســابقتني ‬\n ‫املدونــة بســجله وهــي مخــدرات ومضاربــة صــادق عليهــا فبنــاء علــى‬\n ‫ماتقــدم مــن الدعــوى وإنــكار املدعــى عليــه ملــا جــاء فيهــا وقيــام البينــة‬\n ‫املعدلــه شــرعا علــى ماجــاء يف الدعــوى ونظــرا ملــا جــاء يف التقريــر‬\n ‫الكيميائــي املشــار إليــه بعاليــه فقــد ثبــت لــدي ادانــة املدعــى عليــه‬\n ‫بحيــازة وابتــاع حبــوب محظــوره محتويــه علــى مــادة االميتفامــن ونظــر‬\n\n\n                                                                                         ‫‪140‬‬\n\f      ‫لوجــود ســابقه مماثلــة علــى املدعــى عليــه ونظــر املقاومتــه لرجــال األمــن‬\n      ‫فقــد قــررت احلكــم عليــه مبايلــي ‪ :‬أوال ســجنه ملــدة ســتة اشــهر تبــدأ‬\n      ‫مــن تاريــخ أيقافــه املوافــق ‪1434/3/27‬ه ـ وذلــك بنــاء علــى املــادة (‪)41‬‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــه ثانيــا ‪ :‬جلــده مائــة‬\n      ‫وخمســن جلــده تعزيــرا علــى ثــاث دفعــات كل دفعــة خمســن ســوطا‬\n      ‫بــن كل دفعــة واألخــرى مااليقــل عــن شــهر ثالثــا‪ :‬منعــه مــن الســفر‬\n      ‫خــارج اململكــة بعــد إنتهــاء محكوميتــه وذلــك مــدة ســنتني بنــاء علــى‬\n      ‫املــادة (‪ )56‬مــن النظــام املشــار إليــه وبعــرض احلكــم علــى املدعــى عليــه‬\n      ‫قــرر أعتراضــه علــى احلكــم فأفهــم أن لــه ثالثــون يومــا مــن تاريــخ هــذا‬\n      ‫اليــوم ليقــدم فيهــا اعتراضــه وإالفــإن حقــه يف االعتــراض يســقط كمــا‬\n      ‫قــرر املدعــي العــام االعتــراض علــى احلكــم واكتفــى بالئحــة الدعــوى‬\n      ‫كالئحــة اعتراضيــة  وقــد جــرى تســليم املدعــى عليــه نســخة من احلكم‬\n      ‫يف هــذه اجللســة‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/06/07‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد  ففــي يــوم  اإلثنــن املوافــق‪ 1434/06/19‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 01.00‬ظهــرا  وفيهــا حضــر املدعــى عليــه‬\n      ‫واملثبــت هويتــه يف جلســة ماضيــة وقــد جــرى منــا اإلطــاع علــى الالئحــة‬\n      ‫األعتراضيــة املقدمــة منــه واملقيــدة بهــذه احملكمــة برقــم   وتاريــخ‬\n      ‫‪1434/6/19‬ه ـ واملكونــة مــن خطــاب وثــاث صفحــات فوجــدت يف‬\n      ‫الصفحــة الثانيــة منهــا كالم للمدعــى عليــه مضمونــة اننــي حكمــت‬\n      ‫علــى الفرقــة القابضــة بالســجن خمســة عشــر يــوم لشــهادة زور وبســؤال‬\n      ‫املدعــى عليــه عــن ذلــك أجــاب قائــا اننــي ســمعت ذلــك مــن أحــد‬\n      ‫الســجناء لــدى وال اعلــم صحتــه وأفهمتــه ان ذلــك غيــر صحيــح وان عليــه‬\n\n\n‫‪141‬‬\n\f‫االلتــزام بكتابــة ماهــو متأكــد منــه يف الئحتــه االعتراضيــة واســتعد‬\n‫بذلــك وتراجــع عــن ماهــو مكتــوب وبإطالعــي علــى باقــي الالئحــة لــم‬\n‫أجــد مايؤثــر علــى ماحكمــت بــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n  ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/06/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييز‬\n‫القضايــا اجلزائيــة  مبحكمــة االســتئناف باجلــوف علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمة العامــة بعرعــر برقموتاريخ‪1434/6/24‬ه ـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪ .... /‬املســجل‬\n‫برقمفــي‪1434/6/7‬ه اخلــاص بدعــوى املدعــي العــام ضــد‪ .... /‬يف قضيــة‬\n‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملة‪.‬تقــرر باألكثريــة‬\n‫املصادقــة علــى احلكــم‪.‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                              ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                       ‫‪142‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":136,"source_page_end":142,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bd222f5d116f361ac0bc5917e85d09e3e1aa833302d3ae5495c7dbd24923c91e","normalized_text_hash":"e0cdbb1fa122750a5dbe3643f3fc05c11cfb5f50ca35a2c3cb1fc6df1eb640ef","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p136-34234754"},{"id":"82eb55cd-0d13-5219-8bac-cb95a2ae2d1d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -تعاطي احلشيش املخدر -تعاطي احلبوب اإلمفيتامن احملظورة -التستر على مصدر املخدرات - إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير باملنع من السفر -رد طلب املدعي العام .","document_number":"34282605","case_number":"34234381","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/29","year":"1434","subject":"مخدرات -تعاطي مخدرات -تعاطي احلشيش املخدر -تعاطي احلبوب اإلمفيتامن احملظورة -التستر على مصدر املخدرات - إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير باملنع من السفر -رد طلب املدعي العام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34282605 :‬تاريخه ‪1434/07/29 :‬هـ  ‬\n                            ‫رقم الدعوى‪34234381 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                   ‫‪   34294349‬تاريخه‪1434/8/15 :‬هـ‬\n\n\n\n      ‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬تعاطــي‬\n      ‫احلبــوب اإلمفيتامــن احملظــورة ‪ -‬التســتر علــى مصــدر املخــدرات ‪-‬‬\n      ‫إقــرار ‪ -‬إقامــة حــد املســكر علــى متعاطــي احلشــيش ‪ -‬التعزيــر باملنــع‬\n                                       ‫مــن الســفر ‪ -‬رد طلــب املدعــي العــام ‪.‬‬\n\n\n\n\n                ‫‪ -1‬قول النبي صلى اهلل عليه وسلم ‪ ( :‬كل مسكر حرام ) ‪.‬‬\n                                         ‫‪ -2‬قاعدة ( املرء مؤاخذ بإقراره ) ‪.‬‬\n      ‫‪ -3‬مــا ذكــره أهــل العلــم مــن أن احلشــيش يشــترك مــع اخلمــر يف‬\n                                                          ‫منــاط احلكــم ‪.‬‬\n                      ‫‪ -4‬ما ذكره أهل العلم من تداخل احلدود والتعازير ‪.‬‬\n              ‫‪ -5‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بتعاطــي احلشــيش املخــدر‪  ،‬‬\n        ‫وحبــوب اإلمفيتامــن املنبهــة احملظــورة ‪  ،‬وتســتره على مصدر املخدرات‬\n      ‫وطلــب املدعــي العــام ســجن املدعــى عليــه ومنعــه مــن الســفر بنــاء علــى‬\n      ‫املادتــن (‪ )41‬و (‪ )56‬مــن نظــام مكافحــة املخــدرات ‪،‬حيــث قبــض على‬\n      ‫املدعــى عليــه يف قضيــة جنائيــة وبتحليــل عينــة مــن ســوائله أثبــت التقريــر‬\n\n‫‪143‬‬\n\f‫الكيميائــي إيجابيتهــا ملــادة احلشــيش املخــدر ‪ ،‬كمــا أقــر املدعــى عليــه‬\n‫بتعاطــي احلشــيش املخــدر ‪  ،‬وحبــوب اإلمفيتامــن املنبهــة احملظــورة ‪،‬‬\n‫وأنكــر التســتر علــى مصــدر املخــدرات وطلــب القاضــي مــن املدعــي‬\n‫العــام البينــة علــى تســتر املدعــى عليــه علــى مصــدر املخــدرات‪  ،‬فقــرر‬\n‫بأنــه ليــس لديــه ســوى مــا جــاء يف طيــات املعاملــة ‪ ،‬وبتصفحهــا لــم يجــد‬\n‫القاضــي بينــة علــى تســتر املدعــى عليــه علــى مصــدر املخــدرات ‪،‬بنــاء‬\n‫علــى ماتقــدم حكمــت احملكمــة علــى املدعــى عليــه بحــد املســكر‬\n‫وبتعزيــره مبنعــه مــن الســفر ملــدة ســنتني بعــد تنفيــذ محكوميتــه‪ ،‬ورد‬\n‫القاضــي طلــب املدعــي العــام تعزيــر املدعــى عليــه لقــاء تســتره علــى‬\n‫مصــدر املخــدرات‪ ،‬أقــر املدعــي العــام االعتــراض بالئحــة‪ ،‬وأمــا املدعى‬\n    ‫عليــه فقــد قنــع باحلكــم وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫اجلزائية باألحساء   ‬\n                 ‫ّ‬     ‫احلمد هلل وحده وبعد فلدي أنا القاضي يف احملكمة‬\n   ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة  رئيــس احملكمــة اجلزائيــة يف‬\n     ‫محافظــة األحســاء املكلــف برقــم ‪ 34234381‬وتاريــخ ‪1434/05/21‬‬\n‫هــ  املقيــدة باحملكمــة برقــم ‪ 341240046‬وتاريــخ ‪ 1434/05/21‬ه ـ  ‬\n        ‫ففــي يــوم  الســبت املوافــق ‪ 1434/07/29‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫‪ 11 : 15‬وفيهــا حضــر املدعــي العــام املعمــد بالترافع أمام هذه احملكمة‬\n     ‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n     ‫األحســاء ذي الرقــم  والتاريــخ ‪ 1433/12/01‬ه ـ وادعــى ضــد احلاضــر‬\n‫ا يف دعــواه     ‬‫معــه ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم  قائ ـ ً‬\n     ‫قبــض علــى املدعــى عليــه  أثــر ورود تقريــر الســموم الشــرعي رقــم (‪342‬‬\n\n                                                                                           ‫‪144‬‬\n\f      ‫م أ)لعام‪1434‬هـ   من شــرطة محافظة األحســاء على ذمه قضيه جنائية  ‬\n        ‫والــذي يفيــد بإيجابيــة عينــة البــول املرســلة   ملــادة احلشــيش املخــدر‬\n        ‫واملدرجــة مــن ضمــن املــواد احملظــورة يف اجلــدول رقــم (‪ )1‬فئــة (أ) مــن‬\n        ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املوافــق عليــه باملرســوم‬\n        ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ  وملركبــات األمفيتامــن‬\n        ‫املنبــه احملظــور  واملدرجــة مــن ضمــن املــواد احملظــورة يف اجلــدول رقــم‬\n        ‫(‪ )2‬فئــة (ب) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املوافــق‬\n                      ‫عليــه باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪.‬‬\n        ‫بضبــط أقوالــه‪  /‬أقــر  بتعاطــي احلشــيش املخــدر واحلبــوب احملظــورة‪،‬‬\n            ‫وأفــاد بأنــه يحصــل علــى املخــدرات مــن شــخص كينــي ال يعرفــه ‪.‬‬\n        ‫وقــد اثبــت تقريــر الكيمــاوي الشــرعي رقــم (‪ 342‬م أ) لعــام ‪1434‬ه ـ‬\n        ‫إيجابيــة عينــة البــول املرســلة   ملــادة احلشــيش املخــدر  املــدرج يف اجلــدول‬\n        ‫األول فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪،‬‬\n        ‫وإيجابيــة عينــة البــول املرســلة   ملركــب اإلمفيتامــن  املــدرج يف اجلــدول‬\n        ‫الثانــي فئــة (ب) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪،‬‬\n        ‫وســلبية العينــات املرســلة للخمــر املســكر ‪ .‬وقــد أســفر التحقيــق عــن‬\n        ‫توجيــه االتهــام لــه بتعاطــي احلشــيش املخــدر و حبــوب اإلمفيتامــن‬\n        ‫املنبهــة احملظــورة املجرمــة يف ضــوء الفقــرة الثانيــة مــن املــادة الثالثــة‬\n        ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n        ‫امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪ ،‬وتســتره علــى‬\n                                                                     ‫مصــدر املخــدرات‪.‬‬\n                                                         ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n        ‫‪ -1‬إقــرار املدعــى عليــه املنــوه عنــه املــدون علــى الصفحــة رقــم (‪)3-2‬‬\n\n\n‫‪145‬‬\n\f                                                    ‫املرفــق علــى اللفــة رقــم (‪.)13‬‬\n             ‫‪ -2‬التقرير الكيميائي الشرعي املرفق على اللفة رقم (‪. )4‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور ـ وهــو بكامــل أهليتــه املعتبرة شــرع ًا‬\n‫ـ فعــل محــرم و مجــرم معاقــب عليــه شــرع ًا ونظامـ ًا لــذا اطلــب إثبــات مــا‬\n                                            ‫أســند إليــه واحلكــم عليــه مبــا يلــي ‪-:‬‬\n‫‪ .1‬مبعاقبتــه بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة ( ‪ ) 41‬مــن‬\n‫النظــام املشــار إليــه أعــاه ‪ ،‬و املــادة (‪ )30‬مــن الالئحــة التنفيذيــة لــذات‬\n               ‫النظــام املشــار اليــه أعــاه لقــاء مــا أســند إليهــم مــن اتهــام ‪.‬‬\n‫‪ .2‬معاقبتــه بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة ( ‪ ) 56‬مــن ذات‬\n                            ‫النظــام وذلــك مبنعــه مــن الســفر إلــى خــارج البــاد ‪.‬‬\n‫ال ما ذكــره املدعي العام‬      ‫هــذه دعــواي  وبســؤال املدعــى عليــه أجــاب قائ ً‬\n‫مــن أنــه قبــض علــي مــن قبــل دوريــات األمــن باألحســاء وأنــه مت حتليلــي‬\n‫وأنــه عثــر يف عينــة البــول املرســلة علــى مركبــات احلشــيش املخــدر‬\n‫ومركــب إمفيتامينــي احملظوريــن وأننــي أتعاطاهــا فهــذا كلــه صحيــح‬\n‫وأمــا مــا ذكــره املدعــي العــام مــن أننــي تســترت علــى مصــدر احلشــيش‬\n‫املخــدر واملخــدرات فهــذا كلــه غيــر صحيــح حيــث أننــي حصلــت عليهــا‬\n‫مــن شــخص كينــي هكــذا أجــاب وبســؤال املدعــي العــام هــل لديــه‬\n‫بينــة علــى أن املدعــى عليــه قــام بالتســتر علــى مصــدر  احلشــيش املخــدر‬\n‫ا ليــس لــدي ســوى مــا ذكرتــه يف أوراق املعاملــة‬          ‫واملخــدرات أجــاب قائـ ً‬\n‫هكــذا أجــاب وباإلطــاع علــى املعاملــة وجــد فيهــا علــى لفــة رقــم ‪13‬‬\n‫صحيفــة رقــم ‪ 3-2‬أقــوال املدعــى عليــه والتــي تتطابــق مــع مــا ذكــره‬\n‫املدعــى عليــه يف مجلــس احلكــم كمــا جــرى اإلطــاع علــى املعاملــة‬\n‫وجــد فيهــا علــى لفــة رقــم ‪ 4‬التقريــر الســموم الشــرعية رقــم ‪ 342‬م أ لعــام‬\n\n\n                                                                                           ‫‪146‬‬\n\f      ‫‪1434‬ه ـ واملتضمــن إيجابيــة العينات املرســلة ملركبات احلشــيش املخدر‬\n      ‫وملركــب أمفيتامينــي احملظوريــن ا‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة وإقــرار املدعــى عليــه وحيــث إن املــرء مؤاخــذ بإقــراره ولتقريــر‬\n      ‫الســموم الشــرعية ولقــول النبــي صلــى اهلل عليــه وســلم كل مســكر‬\n      ‫حــرام وحيــث إن احلشــيش يشــترك مــع اخلمــر يف منــاط احلكــم وحيــث‬\n      ‫إن احلــدود والتعازيــر تتداخــل لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى‬\n      ‫عليــه بتعاطــي احلشــيش املخــدر وحبــوب اإلمفيتامــن املنبــة احملظــورة‬\n      ‫ولــم يثبــت لــدي إدانــة املدعــى عليــه بتســتره علــى مصــدر احلشــيش‬\n      ‫املخــدر واملخــدرات وحكمــت عليــه مبــا يلــي ‪ :‬أو ًال ‪ :‬جلــد املدعــى عليــه‬\n      ‫ثمانــن جلــدة دفعــة واحــدة حــد املســكر ثانيـ ًا ‪ :‬رد دعــوى املدعــي العــام‬\n      ‫بخصــوص معاقبــة املدعــى عليــه بالعقوبــة الــواردة يف الفقــرة (‪ )1‬مــن‬\n      ‫املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لعــدم‬\n      ‫وجــود حيــازة ثالثـ ًا ‪ :‬منــع املدعــى عليــه مــن الســفر خــارج اململكــة مــدة‬\n      ‫ســنتني بعــد تنفيــذ محكوميتــه وذلــك مبوجــب املــادة ‪ 56‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة رابعـ ًا ‪ :‬رد دعــوى املدعــي العــام‬\n      ‫بخصــوص معاقبــة املدعــى عليــه لقــاء تســتره علــى مصــدر  احلشــيش‬\n      ‫املخــدر واملخــدرات لعــدم ثبوتهــا وبــه حكمــت وبعــرض الدعــوى علــى‬\n      ‫املدعــي العــام واملدعــى عليــه قــرر املدعــي العــام االعتــراض علــى احلكــم‬\n      ‫وطلــب رفــع املعاملــة إلــى محكمــة االســتئناف بــدون الئحــة فأجبتــه‬\n      ‫لطلبــه وأمــا املدعــى عليــه قــرر قناعتــه بــه وبــه ختمــت اجللســة يف متــام‬\n      ‫الســاعة العاشــرة والنصــف صباحاًوبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/07/29‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n\n\n‫‪147‬‬\n\f  ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n  ‫لــدى احملكمــة برقــم ‪/341980209‬ج‪ 2‬وتاريــخ ‪1434/8/15‬ه ـ‬\n  ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n  ‫املكلــف برقــم ‪ 34/1301126‬وتاريــخ ‪1434/8/9‬ه ـ املرفــق بهــا القــرار‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ /‬املســجل برقــم  ‬\n  ‫وتاريــخ ‪1434/7/29‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ /‬يف قضيــة‬\n  ‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n  ‫فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n  ‫علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                ‫وســلم‪ .‬حــرر يف‪1434/8/21‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                     ‫‪148‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":143,"source_page_end":148,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7bef03a9bdfd1dd358f6a1eb12edc87cc2abef691d95b1e6c45a9a09711c7cf3","normalized_text_hash":"10e3964272d90bbff60463f68e09a89f29e87029242041b5e076bab77d777455","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p143-34282605"},{"id":"d941b6bc-c9bd-5da1-a496-85d4792383e9","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -االشتباه يف تعاطي احلشيش املخدر -درء احلدود بالشبهات -إنكار -عدم وجود بينة -عدم ثبوت إدانة.","document_number":"34226530","case_number":"34246869","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/28","year":"1434","subject":"مخدرات -تعاطي مخدرات -االشتباه يف تعاطي احلشيش املخدر -درء احلدود بالشبهات -إنكار -عدم وجود بينة -عدم ثبوت إدانة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34226530 :‬تاريخه ‪1434/05/28 :‬هـ‬\n                          ‫رقم الدعوى‪34246869 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34253718‬تاريخه‪1434/6/27 :‬هـ‬\n\n\n\n      ‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬االشــتباه يف تعاطــي احلشــيش املخــدر‬\n      ‫‪ -‬درء احلــدود بالشــبهات ‪ -‬إنــكار ‪ -‬عــدم وجــود بينــة ‪ -‬عــدم ثبــوت إدانــة‪.‬‬\n\n\n\n\n                                                  ‫قاعدة ( احلدود تدرأ بالشبهات ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه باتهامــه بتعاطــي احلشــيش‬\n      ‫املخــدر ‪  ،‬اثــر توقيفــه بإصالحيــة احلائــر علــى ذمــة قضيــه أخــرى وطلــب‬\n      ‫املدعــي العــام احلكــم علــى املدعــى عليــه بالتعزيــر بالســجن واملنــع مــن‬\n      ‫الســفر وبتشــديد العقوبــة لقــاء كثــرة ســوابقه وإقامــة حــد املســكر‬\n      ‫عليــه‪  -‬حيــث مت االشــتباه مبجموعــة مــن الســجناء يف إصالحيــة احلائــر‬\n      ‫بتعاطــي املخــدرات ‪ ،‬ومت إرســال املدعــى عليــه للمركــز الصحــي ‪،‬‬\n      ‫ألخــذ عينــة منــه ‪ ،‬وإرســالها للتحليــل ‪ ،‬وقــد أثبــت التقريــر الكيمائــي‬\n      ‫إيجابيــة العينــة للمــادة الفعالــة للحشــيش املخــدر ‪  -‬أنكــر املدعــى عليــه‬\n      ‫مــا جــاء يف دعــوى املدعــي العــام وبطلــب البينــة مــن املدعــي العــام قــرر‬\n      ‫أنــه ليــس لديــه ســوى مــا قدمــه يف أوراق القضيــة‪  ،‬لــم يجــد القاضــي‬\n      ‫إ َّال حتليـ ًـا داخــل الســجن ‪ ،‬وأفــاد املدعــى عليــه بأنــه قــد يكــون شــم‬\n      ‫احلشــيش ‪ ،‬داخــل الســجن‪ ،‬اثــر اختالطــه مــع أنــاس بعضهــم يتعاطــى‬\n\n‫‪149‬‬\n\f‫احلشــيش ‪ ،‬كونــه ســجني معهــم و لــم يثبــت املدعــي العــام مــا جــاء يف‬\n‫دعــواه‪ ،‬وبنــاء علــى ماتقــدم حكمــت احملكمــة بصــرف النظــر عــن‬\n‫مطالبتــه بحــد املســكر ‪  ،‬وغيــره ‪  ،‬بحــق املدعــى عليــه ـ ـ وقــرر املدعــي‬\n‫العــام اعتراضــه بــدون الئحــة ‪  ،‬واملدعــى عليــه قــرر القناعــة باحلكــم و‬\n                                  ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا القاضي يف احملكمة اجلزائية بالرياض   ‬\n   ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n   ‫بالريــاض برقــم  وتاريــخ ‪ 1434/05/28‬هــ  املقيــدة باحملكمــة برقــم‬\n   ‫وتاريــخ ‪ 1434/05/28‬هــ  ففــي يــوم  الثالثــاء املوافــق‪ 1434/05/28‬ه ـ‬\n   ‫افتتحــت اجللســة الســاعة ‪  11 : 15‬وفيهــا قــدم املدعــي العــام دعــواه ضــد‬\n   ‫‪ ....../‬البالــغ مــن العمــر (‪ )38‬عام ـ ًا ســعودي بالهويــة رقــم (‪ )....‬أعــزب‬\n   ‫موظــف حكومــي متعلــم يقيــم مبحافظــة املجمعــة ‪ ،‬موقــوف بتاريــخ‬\n   ‫‪1427/11/05‬ه ـ لــدى إصالحيــة احلائــر علــى ذمــة قضيــة طعــن مبوجــب‬\n   ‫مذكــرة توقيــف رقــم (‪ )....‬وتاريــخ ‪1427/11/08‬ه ـ ‪ .‬حيــث إنــه بتاريــخ‬\n   ‫‪1432/08/25‬ه ـ مت االشــتباه مبجموعــة مــن ســجناء إصالحيــة احلائــر‬\n   ‫تــدور حولهــم الشــبهات بتعاطــي املخــدرات ومت بعــث املذكــور ملركــز‬\n   ‫صحــي إصالحيــة احلائــر ألخــذ عينــة منــه وإرســالها للتحليــل ‪ .‬وقــد أثبــت‬\n   ‫التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقــب الســموم‬\n   ‫والكيميــاء الطبيــة الشــرعية املرفــق رقــم (‪/9022‬س) لعــام ‪1432‬ه ـ‬\n   ‫إيجابيــة عينــة مســتخلص بــول املذكــور للمــادة الفعالــة للحشــيش وهــو‬\n   ‫مــن املــواد املخــدرة واملدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام‬\n\n                                                                                       ‫‪150‬‬\n\f      ‫مكافحــة املخــدرات واملؤثــرات الصــادر باملرســوم امللكــي رقــم م‪39/‬‬\n      ‫يف ‪1426/7/8‬ه ـ وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام‬\n      ‫إلــى ‪ /‬بتعاطــي احلشــيش املخــدر املجــرم مبوجــب املــادة (الثالثة) من نظام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n      ‫(م‪ )39/‬وتاريــخ ‪1426/07/08‬ه ـ ‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪1 :‬ـ‬\n      ‫مــا تضمنــه محضــر القبــض املنــوه عنــه املرفــق لفــة رقــم (‪2 . )1‬ـ مــا‬\n      ‫تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة رقــم (‪. )2‬‬\n      ‫وببحــث ســوابقه اتضــح وجــود أربــع ســوابق مســجلة عليــه حتــى تاريخــه‬\n      ‫األولــى ســابقة مضاربــة ‪ ،‬والثانيــة ســابقة معاكســة مقترنــة بالتلفــظ‬\n      ‫بألفــاظ غيــر الئقــة ‪ ،‬والثالثــة ســابقة مضاربــة ‪ ،‬والرابعــة ســابقة‬\n      ‫التهديــد مقترنــة بإطــاق نــار وحيــازة ســاح بــدون ترخيــص ‪ ،‬وتبــن‬\n      ‫وجــود قضيــة مخــدرات عليــه برقــم (‪ ).....‬صــدر بهــا القــرار الشــرعي‬\n      ‫رقــم (‪ ).....‬وتاريــخ ‪1427/8/8‬ه ـ ‪ .‬وحيــث إن مــا أقــد عليــه املذكــور‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب إثبــات إدانتــه مبــا‬\n      ‫اســند إليــه واحلكــم عليــه باآلتــي ‪1 :‬ـ إجــراء املقتضــى الشــرعي بحقــه‬\n      ‫وفق ـ ًا للفقــرة ( األولــى ) مــن املــادة (‪ )41‬الواحــدة واألربعــن مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة إليــه لتعاطيــه احلشــيش املخــدر‬\n      ‫‪2 .‬ـ منعــه مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء فتــرة تنفيــذ عقوبــة‬\n      ‫ســجنه وفقـ ًا للفقــرة ( األولــى ) مــن املــادة (‪ )56‬مــن نفــس النظــام املشــار‬\n      ‫إليــه ‪3  .‬ـ تشــديد العقوبــة عليــه لكثــرة ســوابقه اســتناد ًا لبرقيــة ســمو‬\n      ‫نائــب وزيــر الداخليــة رقــم ( ‪ )93958/5/5/1‬وتاريــخ ‪1429/8/23‬ه ـ‬\n      ‫‪ .‬هــذه دعــواي ‪  ،‬وبســؤال املدعــى عليــه أجــاب بقولــه إن مــا ذكــره‬\n      ‫املدعــي العــام غيــر صحيــح فلــم أتعاطــى احلشــيش املخــدر وســوابقي‬\n\n\n‫‪151‬‬\n\f‫صحيحــة هكــذا أجــاب وبطلــب البينــة مــن املدعــي العــام قــال بينتــي‬\n‫مــا يف األوراق وبالرجــوع لــأوراق وجــدت أن التهمــة مبنيــة علــى حتليــل‬\n‫داخــل الســجن وبعــرض ذلــك علــى املدعــى عليــه قــال إننــي محكــوم‬\n‫علــي يف قضيــة أخــرى خمســة عشــر ســنة وقــد أمضيــت ســبع ســنوات‬\n‫وبقــي ثمــان ســنوات وأختلــط بســجناء كثيريــن ورائحــة الســجن تفــوح‬\n‫بــكل شــيء ورمبــا أصابنــي شــي مــن روائــح املــدة الطويلــة هكــذا قــرر‬\n‫كمــا وجــدت أن املدعــى عليــه منكــر بــاألوراق مــا نســب إليــه كمــا‬\n‫وجــدت خطــاب مديــر شــعبة إصالحيــة احلائــر تتضمــن أن املذكــور‬\n‫موقــوف لديهــم يف قضيــة طعــن ودهــس شــخص وصــدر بحقــه القــرار‬\n‫الشــرعي املتضمــن ســجنه ملــدة خمســة عشــر ســنة وجلــده ثالثــة آالف‬\n‫جلــدة فبنــاء علــى مــا تقــدم وحيــث أن هــذه الدعــوى أقيمــت بنــاء علــى‬\n‫حتليــل واملذكــور يختلــط بســجناء آخريــن مــن مــدة طويلــة ولــم يعثــر‬\n‫بحوزتــه علــى شــيء ولــم يشــاهد يتعاطــى شــيء وإمنــا ورود شــبهه فقــط‬\n‫وال يوجــد تقريــر كيمــاوي بذلــك واحلــدود تــدرأ بالشــبهات لــذا لــم يثبــت‬\n‫لــدي إدانــة املدعــى عليــه بشــيء‪ ،‬وصرفــت النظــر عــن مطالبــة املدعــي‬\n‫العــام بحــد املســكر وغيــره وبــه حكمــت وبعــرض احلكــم علــى‬\n‫احملكــوم عليــه قــرر القناعــة أمــا املدعــي العــام فقــد طلــب اســتئنافه‬\n‫مكتفي ـ ًا بالئحــة الدعــوى ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪1434/05/28‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض  برقــم‬\n‫وتاريــخ ‪1434/6/6‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n\n\n                                                                                   ‫‪152‬‬\n\f        ‫باحملكمــة الشــيخ‪ /‬املســجل برقــم  وتاريــخ ‪1434/5/28‬ه ـ اخلــاص‬\n        ‫بدعــوى املدعــي العــام ضــد ‪ /‬التهامــه بقضيــة مخــدرات علــى النحــو‬\n      ‫املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‪  .‬‬\n        ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n        ‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                ‫وســلم‪.‬‬\n\n\n\n\n‫‪153‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":149,"source_page_end":153,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c3841b1d105b4c4082a40f3f7695b4c2d15de08261211a93427795c61d0eb942","normalized_text_hash":"b0f262d0e312987c3d83474b656e4e9df0c09acdbe94c2625b2a1f33adafed98","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p149-34226530"},{"id":"7b2a521c-b18e-5383-9a11-d9352d6c51c0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش واحلبوب احملظورة إقرار -حد املسكر -التعزير باملنع من السفر -رد دعوى املدعي العام .","document_number":"34263866","case_number":"34302423","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/10","year":"1434","subject":"مخدرات -تعاطي احلشيش واحلبوب احملظورة إقرار -حد املسكر -التعزير باملنع من السفر -رد دعوى املدعي العام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪  34263866:‬تاريخه ‪1434/07/10 :‬هـ‬\n                          ‫رقم الدعوى‪34302423 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34314421‬تاريخه‪1434/09/08 :‬هـ‬\n\n\n\n      ‫مخــدرات ‪ -‬تعاطــي احلشــيش واحلبــوب احملظــورة ـ إقــرار ‪ -‬حــد املســكر‬\n                        ‫‪ -‬التعزيــر باملنــع مــن الســفر ‪ -‬رد دعــوى املدعــي العــام ‪.‬‬\n\n\n\n      ‫‪.1‬ـ قولــه صلــى اهلل عليــه وســلم «مــن شــرب اخلمــر فاجلــدوه» رواه‬\n                                             ‫أحمــد‪ ،‬وأبــو داوود ‪ ،‬والنســائي ‪.‬‬\n      ‫‪.2‬ـ إجمــاع الصحابــة ‪ -‬رضــي اهلل عنهــم ‪ -‬علــى جلــد شــارب اخلمــر‬\n                         ‫ثمانــن جلــدة‪ ( .‬ينظــر ‪ :‬كشــاف القنــاع ‪)99/14‬‬\n      ‫‪.3‬ـ جلــد شــارب اخلمــر ثمانــن هــو املذهــب عنــد احلنابلــة ‪ ،‬وعليــه‬\n                       ‫جماهيــر األصحــاب‪ ( .‬ينظــر ‪ :‬اإلنصــاف ‪.)441/15‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه األول والثانــي بشــرب املســكر‪،‬‬\n      ‫واألول كذلــك بتعاطــي احلشــيش املخــدر‪ ،‬واحلبــوب املنبهــة احملظــورة‪،‬‬\n      ‫طلــب املدعــي العــام إقامــة احلــد عليهمــا لقــاء شــربهما للمســكر وطلــب‬\n      ‫املدعــي العــام بحبــس املدعــى عليــه األول ومنعــه مــن الســفر تطبيقــا‬\n      ‫ألحــكام املــواد أرقــام (‪ )41‬و (‪ )56‬مــن نظــام مكافحــة املخــدرات‪،‬‬\n      ‫حيــث أنــه أثنــاء قيــام نقطــة تفتيــش بأحــد األحيــاء ‪ ،‬مت اســتيقاف‬\n      ‫الســيارة وكانــت بقيــادة املدعــى عليــه األول ومعــه املدعــى عليــه الثاني‪،‬‬\n\n‫‪161‬‬\n\f  ‫أقــر  املدعــى عليــه األول بالدعــوى‪ ،‬وعثــر بجوالــه علــى صــور ســجائر‬\n‫ملفوف وحبوب منبهة ‪ ،‬وباســتجوابهما اعترف  األول بشــرب املســكر  ‬\n  ‫وتعاطــي احلشــيش املخــدر ‪  ،‬واحلبــوب املنبهــة احملظــورة و اعترف  الثاني‬\n  ‫بشــرب املســكر‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بجلــد املدعى‬\n  ‫عليــه األول والثانــي  حــد املســكر و احلكــم بتطبيــق املــادة (‪ )56‬مــن‬\n  ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة بحــق املدعــى عليــه األول‬\n  ‫ومنعــه مــن الســفر‪ ،‬رد دعــوى املدعــي العــام ضــد املدعــى عليــه األول‬\n  ‫بتطبيــق املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n  ‫لعــدم انطباقهــا بحقــه وقنــع املدعــى عليــه األول باحلكــم ‪ ،‬وقنــع املدعــى‬\n  ‫عليــه الثانــي باحلكــم ‪ ،‬واعتــرض املدعــي العــام علــى احلكــم بــدون‬\n                          ‫الئحــة وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                     ‫‪162‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا‪ ......‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n      ‫مــن هيئــة التحقيــق واإلدعــاء العــام واملقيــدة لــدى احملكمــة برق ـم  ‬\n        ‫وتاريــخ ‪1434/7/1‬ه ـ واحملالــة لنــا مــن فضيلة رئيــس احملكمة اجلزائية‬\n        ‫بالدمــام برقــم ‪ ......‬وتاريــخ ‪1434/7/1‬ه ـ افتتحــت اجللســة يف يــوم‬\n        ‫االثنــن ‪1434/7/10‬ه ـ الســاعة الثامنــة والنصــف وفيهــا قــدم املدعــي‬\n        ‫العــام دعــواه ونصهــا اآلتــي‪ :‬بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام‬\n        ‫لفــرع املنطقــة الشــرقية أدعــي علــى كل مــن‪ ...... -1 /‬ســعودي اجلنســية‬\n        ‫مبوجــب الســجل املدنــي رقــم‪  ...... -2/‬أردانــي اجلنســية مبوجــب رخصــة‬\n        ‫اإلقامــة رقــم ‪  ......‬حيــث إنــه يف يــوم الســبت ‪1434/6/3‬ه ـ أثنــاء قيــام‬\n        ‫نقطــة تفتيــش بحــي الكورنيــش بالدمــام طريــق امللــك عبــداهلل مت‬\n        ‫اســتيقاف ســيارة مــن نــوع (‪ )......‬حتمــل لوحــة رقــم (‪ )....‬بقيــادة املدعــى‬\n        ‫عليــه  ويرافقــه وقــد اتضــح أن املدعــى عليــه األول عنــد القبــض  بحالــة‬\n      ‫غيــر طبيعيــة وباستشــمامه لوحــظ انبعــاث رائحــة املســكر مــن أنفاســه‬\n      ‫وبتفتيــش جهــازه النقــال عثــر علــى صــور ســجائر ملفــوف وحبــوب منبــه‬\n      ‫محظــورة وباســتجواب األول أقــر بأنــه يشــرب املســكر ويتعاطــى‬\n      ‫احلشــيش املخــدر واحلبــوب املنبهــة واحملظــورة وباســتجواب الثانــي أقــر‬\n      ‫بأنــه يشــرب املســكر وانتهــى التحقيــق التهــام األول بشــرب املســكر‬\n      ‫وتعاطيــه للحشــيش املخــدر واحلبــوب املنبهــة واحملظــورة واتهــام الثانــي‬\n      ‫بشــربه املســكر وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬اعترافهمــا مبــا‬\n      ‫نــوه عنهمــا املــدون مبحضــر اســتجوابهما املرفــق علــى اللفــة رقــم (‪)8-5‬‬\n\n‫‪163‬‬\n\f  ‫‪ -2‬محضــر تنفيــذ املهمــة املنــوه عنــه املرفــق علــى اللفــة رقــم (‪-3 )2‬‬\n  ‫محضــر االستشــمام املنــوه عنــه بحــق املتهــم ‪ ......‬املــدون علــى الصفحــة‬\n  ‫رقــم (‪ )6‬مــن ملــف التحقيــق املرفــق علــى اللفــة رقــم (‪ )1‬وبالبحــث‬\n  ‫عــن ســوابقهما لــم يعثــر لهمــا علــى ســوابق وحيــث إن مــا أقــدم عليــه‬\n  ‫املدعــى عليهمــا املذكــوران وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا‬\n  ‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب اآلتــي‪ :‬أوال‪ :‬إثبــات إدانتهمــا‬\n  ‫بشــرب املســكر واحلكــم عليهمــا بحــد الســكر لقــاء ذلــك‪ .‬ثانيــا‪:‬‬\n  ‫إثبــات إدانــة املدعــى عليــه ‪ ......‬مبــا أســند إليــه مــن تعاطيــه للحشــيش‬\n  ‫املخــدر واحلبــوب املنبهــة واحملظــورة وفقـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم‬\n  ‫(‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه‬\n  ‫مبــا يلــي‪ -1 :‬بعقوبــة الســجن الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n  ‫(‪ )41‬مــن النظــام ‪ -2‬منعــه مــن الســفر وفقـ ًا للفقــرة رقــم (‪ )1‬مــن املــادة‬\n  ‫رقــم (‪ )56‬مــن النظــام هكــذا ادعــى وبعــرض دعــوى املدعــي العــام‬\n  ‫ا مــا ذكــره املدعــي العــام مــن‬    ‫علــى املدعــى عليــه الثانــي أجــاب قائ ـ ً‬\n  ‫شــربي للمســكر فذلــك صحيــح حيــث قــد ســبق وأن شــربته يف دولــة‬\n  ‫ـاء علــى مــا‬\n               ‫البحريــن هكــذا أجــاب وأمــا املدعــى عليــه فلــم يحضــر فبنـ ً‬\n  ‫تقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى عليــه وإقــراره بالدعــوى‬\n  ‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ولقولــه صلــى اهلل عليــه وســلم (مــن‬\n  ‫شــرب اخلمــر فاجلــدوه) رواه أحمــد وأبــو داود والنســائي كمــا انعقــد‬\n  ‫إجمــاع الصحابــة رضــي اهلل عنهــم علــى جلــد شــارب اخلمــر ثمانــون جلــدة‬\n  ‫(كشــاف القنــاع عــن اإلقنــاع ‪ )99/14‬وهــو املذهــب وعليــه جماهيــر‬\n‫األصحــاب (اإلنصــاف ‪ )441/15‬لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه  ‬\n  ‫بشــرب اخلمــر املســكر وقــررت عقابــه علــى ذلــك باجللــد ثمانــن جلــدة‬\n\n\n                                                                                            ‫‪164‬‬\n\f      ‫دفعــة واحــدة حــد املســكر ويكــون التنفيــذ يف مــكان عــام يحضــره‬\n      ‫جمــع مــن النــاس وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن‬\n      ‫قــرر املدعــى عليــه القناعــة باحلكــم كمــا قــرر املدعــي العــام عــدم‬\n      ‫االعتــراض وجــرى إفهــام املدعــي العــام بأنــه ســوف يتــم نظــر الدعــوى‬\n      ‫بحــق املدعــى عليــه يف حــال حضــوره وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n                                      ‫علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/7/10‬ه ـ‬\n      ‫احلمــدهلل وحــده وبعــد ففــي يــوم االثنــن ‪1434/7/10‬ه ـ حضــر املدعــي‬\n      ‫العــام كمــا حضــر املدعــى عليــه وبعــرض دعــوى املدعــي العــام علــى‬\n      ‫ا مــا ذكــره املدعــي العــام كلــه صحيــح‬   ‫املدعــى عليــه األول أجــاب قائـ ً‬\n      ‫فقــد ســبق وأن تعاطيــت املســكر واحلشــيش املخــدر واحلبــوب احملظــورة‬\n      ‫قبــل عــدة أشــهر وتركتهــا اآلن ولــم يحكــم علــي وال توجــد لدي ســوابق‬\n      ‫هكــذا أجــاب ثــم جــرى الرجــوع إلــى املعاملــة فوجــدت علــى لفــة رقــم‬\n      ‫(‪ )1‬دفتــر التحقيــق ص (‪ )8‬محضــر استشــمام املتضمــن انبعــاث رائحــة‬\n      ‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n                                               ‫املســكر مــن املدعــى عليــه فبنـ ً‬\n      ‫العــام وإجابــة املدعــى عليــه وإقــراره بالدعــوى وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا وبنــاء علــى الفقــرة (‪ )2‬مــن املــادة (‪ )3‬والفقــرة (‪ )1‬مــن‬\n      ‫املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات املؤثــرات العقلــي وبنــاء‬\n      ‫علــى املــادة (‪ )30‬مــن الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة لــذا فقــد ثبــت لــدي تعاطــي املدعــى عليــه للحشــيش‬\n      ‫املخــدر واحلبــوب احملظــورة وشــربه للمســكر وقــررت عقابــه علــى‬\n      ‫ذلــك باآلتــي‪ :‬أوالً‪ :‬رد مطالبــة املدعــي العــام بتطبيــق الفقــرة (‪ )1‬مــن‬\n      ‫املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات لعــدم انطباقهــا‪ .‬ثانيـاً‪ :‬جلــد‬\n      ‫املدعــى عليــه ثمانــن جلــدة دفعــة واحــدة حــد املســكر ويكــون التنفيــذ‬\n\n\n‫‪165‬‬\n\f‫يف مــكان عــام يحضــره جمــع مــن النــاس لقــاء شــربه احلشــيش املخــدر‬\n‫وشــربه للمســكر‪ .‬ثالثـاً‪ :‬منــع املدعــى عليــه مــن الســفر ملــدة ســنتني تبــدأ‬\n‫مــن تاريــخ احلكــم‪ .‬وبــكل مــا تقــدم حكمــت وبعــرض احلكــم علــى‬\n‫الطرفــن قــرر املدعــى عليــه القناعــة باحلكــم وأمــا املدعــي العــام فقــرر‬\n‫عــدم القناعــة باحلكــم وطلــب االســتئناف بالئحــة يقدمهــا فأفهمتــه بأنه‬\n‫ســوف يجــري بعــد قليــل تســليمه نســخة مــن احلكــم ليقــدم اعتراضــه‬\n‫خــال ثالثــن يوم ـ ًا مــن اآلن يكــون حقــه يف االســتئناف بعــد مضــي‬\n‫هــذه املــدة ســاقط ًا ففهــم ذلــك واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n                                              ‫محمــد‪ .‬حــرر يف ‪1434/07/10‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اخلميــس ‪1434/10/29‬ه ـ افتتحــت‬\n‫اجللســة الســاعة الثامنــة إال ربــع وفيهــا وردتنــا املعاملــة مــن محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية برقــم ‪ 34/2270787‬يف ‪1434/10/8‬ه ـ‬\n‫وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم ‪ ......‬يف‬\n‫‪1434/9/8‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق وصلــى‬\n‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                   ‫‪1434/10/29‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم وتاريــخ ‪1434/9/1‬ه ـ الــواردة مــن فضيلــة رئيــس‬\n‫احملكمة اجلزائية مبدينة الدمام املكلف برقم وتاريخ ‪1434/8/23‬هـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪......‬‬\n‫املســجل برقــم ‪ ......‬وتاريــخ ‪1434/7/10‬ه ـ اخلــاص بدعــوى‪ ......‬املدعــي‬\n‫كل مــن ‪( ...... /2 ...... /1‬أردنــي اجلنســية) يف قضيــة‬       ‫العــام ضــد‪ٍ ......‬‬\n\n                                                                                         ‫‪166‬‬\n\f      ‫خمــور وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n      ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n                                                            ‫حــرر يف ‪1434/9/6‬هــ‪.‬‬\n\n\n\n\n‫‪167‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":161,"source_page_end":167,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"959e92df72f13ade7085726489f5b26cd445f588964b92dd52d5c5e239577965","normalized_text_hash":"1937176e678d87e1aec9604908b96afc50b784bc6bfa761aad14973d199d143b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p161-34263866"},{"id":"7bf2f41c-a052-55f4-b0e6-69f5d297da37","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -تعاطي الهروين املخدر -التستر على مصدر املخدرات -إقرار -إقامة حد املسكر على متعاطي الهروين- التعزير باملنع من السفر.","document_number":"3426950","case_number":"34303614","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/9","year":"1434","subject":"مخدرات -تعاطي مخدرات -تعاطي الهروين املخدر -التستر على مصدر املخدرات -إقرار -إقامة حد املسكر على متعاطي الهروين- التعزير باملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪  3426950 :‬تاريخه ‪1434/07/9 :‬هـ‬\n                   ‫رقم الدعوى‪34303614 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n    ‫تاريخه‪1434/8/1 :‬هـ‬         ‫‪34284262‬‬\n\n\n\n‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬تعاطــي الهرويــن املخــدر ‪ -‬التســتر علــى‬\n‫مصــدر املخــدرات ‪ -‬إقــرار ‪ -‬إقامــة حــد املســكر علــى متعاطــي الهرويــن‪-‬‬\n                                               ‫التعزيــر باملنــع مــن الســفر‪.‬‬\n\n\n\n\n            ‫‪-1‬قول النبي صلى اهلل عليه وسلم ‪ ( :‬كل مسكر حرام ) ‪.‬‬\n                                   ‫‪-2‬قاعدة ( املرء مؤاخذ بإقراره ) ‪.‬‬\n          ‫‪-3‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه بتعاطــي الهرويــن املخــدر‪،‬‬\n‫وتســتره علــى مصــدر املخــدرات‪ ،‬وطلــب املدعــي العــام تعزيــر املدعــى‬\n‫عليــه بالســجن واملنــع مــن الســفر وتطبيــق املــواد (‪ ) 56/ 41‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة بحقــه واملــادة رقــم ‪ 30‬مــن‬\n‫الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫وتعزيــره لقــاء تســتره علــى مصــدر هــذه املخــدرات ‪ ،‬أقــر املدعــى عليــه‬\n‫بتعاطــي الهيرويــن املخــدر أثنــاء التحقيــق معــه يف قضيــة قتــل وأقــر‬\n‫املدعــى عليــه أنــه قــام بإخبــار اجلهــة األمنيــة مبصــدر املخــدرات وأنكــر‬\n‫التســتر وطلــب القاضــي مــن املدعــي العــام البينــة علــى تســتر املدعــى‬\n\n                                                                                    ‫‪168‬‬\n\f      ‫عليــه علــى مصــدر املخــدرات‪  ،‬فقــرر بأنــه ليــس لديــه ســوى مــا جــاء يف‬\n      ‫طيــات املعاملــة‪  ،‬وبتصفحهــا لــم يجــد القاضــي بينــة علــى تســتر املدعــى‬\n      ‫عليــه علــى مصــدر املخــدرات بنــاء علــى مــا تقــدم حكمــت احملكمــة‬\n      ‫علــى املدعــى عليــه بحــد املســكر‪ ،‬والتعزيــر باملنــع مــن الســفر ورد‬\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليــه حيــال مــا جــاء يف طلبــه تطبيــق‬\n      ‫املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة بحــق‬\n      ‫املدعــى عليــه‪ ،‬قــرر املدعــي العــام االعتــراض بالئحــة ‪  ،‬وأمــا املدعــى‬\n      ‫عليــه فقــد قنــع باحلكــم ‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n        ‫اجلزائيــة‬\n           ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة‬\n        ‫باالحســاء  وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة  رئيــس احملكمــة‬\n      ‫اجلزائيــة يف محافظــة االحســاء املكلــف برقــم  وتاريــخ ‪1434/07/02‬هـ  ‬\n        ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪1434/07/02‬هــ  ففــي يــوم  األحــد‬\n        ‫املوافق ‪1434/07/09‬هـ افتتحت اجللســة الســاعة ‪ 09 : 45‬وفيها حضر‬\n        ‫املدعــي العــام وادعــى ضــد احلاضــر معــه  ‪ ......‬ســعودي اجلنســية مبوجــب‬\n        ‫الســجل املدنــي رقــم ‪  ......‬قائــا يف دعــواه باإلطــاع علــى خطــاب مديــر‬\n        ‫شــرطة محافظة األحســاء رقم (‪9/21‬ق‪ )7286/‬وتاريخ‪1433/8/10‬هـ‬\n        ‫املتضمــن إحالــة األوراق املفــرزة مــن ملــف التحقيــق مــع املدعــى عليــه‬\n        ‫يف قضيــة قتــل ملــا تضمنــه التحقيــق مــن إقــرار املدعــى عليــه بتعاطيــه‬\n        ‫للهرويــن املخــدر وإحالــة األوراق إلــى مكافحــة املخــدرات بحكــم‬\n        ‫االختصــاص وبتاريخ‪1434/6/4‬ه ـ وبنــاء علــى أمــر مــن مديــر العمليــات‬\n        ‫مبكافحــة املخــدرات املبنــي علــى خطــاب مديــر القضايــا واملوقوفــن‬\n\n‫‪169‬‬\n\f‫رقــم (‪ )309‬وتاريخ‪1434/5/20‬ه ـ املتضمــن طلــب البحــث والقبــض‬\n‫علــى املدعــى عليــه والــذي اتضــح بأنــه يعمــل ســكرتي مبستشــفى‬\n‫وبالتنســيق مــع الرئيــس املباشــر أفــاد بــأن املدعــى عليــه يتواجــد مبركز‬\n‫طــب األســنان وســوف يقــوم بإرشــاد الفرقــة إليــه ‪ ،‬ويف متــام الســاعة‬\n‫العاشــرة صباح ـ ًا مت القبــض علــى املدعــى عليــه وباســتجواب املدعــى‬\n‫عليــه أقــر بتعاطيــه للهيرويــن املخــدر قبــل القبــض عليــه بثالثــة أســابيع‬\n‫وشــرائها مــن شــخص يف مدينــة اخلبــر ال يعرفــه وانتهــى التحقيــق معــه‬\n‫إلــى توجيــه االتهــام لــه بتعاطــي الهيرويــن املخــدر املجــرم مبوجــب املــادة‬\n‫(الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى‬\n‫مصــدر املخــدرات وذلــك لألدلــة والقرائــن التاليــة ‪1 :‬ـ مــا جــاء يف إقــراره‬\n‫املنــوه عنــه واملــدون علــى الصفحــات رقــم (‪ )5،4،3‬مــن دفتــر االســتدالل‬\n‫لفــة رقــم (‪2 )13‬ـ مــا جــاء يف خطــاب مديــر شــرطة محافظــة األحســاء‬\n‫املرفــق لفــة رقــم (‪ )6‬وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل‬\n‫أهليتــه املعتبــرة شــرع ًا فعــل مجــرم ومعاقــب علي ــه نظام ـ ًا لــذا أطلــب‬\n                             ‫إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n‫‪-1‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن النظــام املشــار‬\n              ‫إليــه واملــادة (‪ )30‬مــن الالئحــة التنفيذيــة لقــاء مــا أســند إليــه‬\n‫‪2‬ـ بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام مبنعــه‬\n                                              ‫مــن الســفر بعــد تنفيــذ محكوميتــه‬\n         ‫‪3‬ـ عقوبة تعزيرية لقاء تستره على مصدر املخدرات هذه دعواي ‪.‬‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n‫العــام مــن أننــي اســتخدمت الهيرويــن املخــدر وكان ذلــك قبــل القبــض‬\n\n\n                                                                                           ‫‪170‬‬\n\f      ‫علــي بثالثــة أســابيع فهــذا كلــه صحيــح وأنــا تائــب ونــادم وأمــا ما ذكره‬\n      ‫املدعــي العــام مــن تســتري علــى مصــدره فغيــر صحيــح حيــث إننــي‬\n      ‫أخبرتهــم بأنــي أحتصــل عليهــا مــن شــخص باكســتاني يف اخلبــر عــن‬\n      ‫طريــق بطاقــات ‪ .....‬هكــذا أجــاب وبســؤال املدعــي العــام هــل لديــه بينــة‬\n      ‫علــى تســتر املدعــى عليــه علــى مصــدر املخــدرات أجــاب قائــا بينتــي مــا‬\n      ‫ذكرتــه يف أوراق املعاملــة هكــذا أجــاب وباإلطــاع علــى املعاملــة وجــد‬\n      ‫أن أقــوال املدعــى عليــه يف دفتــر التحقيــق مطابقــة ملــا ذكــره يف جوابــه‬\n      ‫يف مجلــس احلكــم فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإقــرار‬\n      ‫املدعــى عليــه وحيــث إن املــرء مؤاخــذ بإقــراره وحيــث إن املدعــى عليــه‬\n      ‫أنكــر تســتره علــى مصــدر الهيرويــن واملدعــي العام لم يحضــر بينة على‬\n      ‫ذلــك ولقــول النبــي صلــى اهلل عليــه وســلم كل مســكر حــرام وحيــث إن‬\n      ‫الهيرويــن يشــترك مــع اخلمــر يف منــاط احلكــم فيأخــذ حكمــه لذلــك‬\n      ‫كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه بتعاطــي الهيرويــن املخــدر ولــم‬\n      ‫يثبــت لــدي تســتره علــى مصــدره وحكمــت مبــا يلــي ‪ :‬أو ًال ـ جلــد املدعــى‬\n      ‫عليــه ثمانــون جلــده حــد املســكر دفعــه واحــدة ثانيـ ًا ـ منــع املدعــى عليــه‬\n      ‫من الســفر خارج اململكة مدة ســنتني بعد تنفيذ مدة محكوميته ثالث ًا‬\n      ‫ـ رد دعــوى املدعــي العــام بخصــوص معاقبــة املدعــى عليــه مبوجــب املــادة‬\n      ‫‪ 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وعلــى تســتره لعــد‬\n      ‫ثبوتهــا وبــه حكمــت وبعــرض ذلــك علــى املدعــى عليــه و املدعــي العــام‬\n      ‫قــرر املدعــى عليــه قناعتــه بــه بينمــا قــرر املدعــي العــام عــدم قناعتــه‬\n      ‫وطلــب االســتئناف فأجبتــه لطلبــه وقــرر بأنــه لــن يقــدم الئحــة اعتراضيــة‬\n      ‫وإمنــا يكتفــي بــأوراق املعاملــة والئحــة الدعــوى وختمــت اجللســة يف متــام‬\n      ‫الســاعة ‪ 10 : 15‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n‫‪171‬‬\n\f                                    ‫وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/07/09‬ه ـ‬\n  ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n  ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n  ‫مــن فضيلــة  القائــم بعمــل رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء‬\n  ‫املكلــف برقــم ‪ ......‬وتاريــخ ‪1434/7/12‬ه ـ املقيــدة لــدى احملكمــة‬\n  ‫برقــم وتاريــخ ‪1434/7/16‬هــ  املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ املســجل برقــم   وتاريــخ ‪1434/7/9‬هــ  ‬\n  ‫اخلــاص بدعــوى‪ ......‬املدعــي العــام ضــد‪ ......‬املدعــى عليــه يف قضيــة‬\n  ‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n  ‫فيــه ‪ .‬وبدراســة  القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n  ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                   ‫وســلم حرريف‪1434/7/30‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                           ‫‪172‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":168,"source_page_end":172,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fea75d7070861cd94ab3662f64340ce8440151e889eb5c298fe95e7af45f8c98","normalized_text_hash":"2c8b8cb67bed68f9e12e352bb76aa7d7f85059efdb2302d981a4ffb489297ab4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p168-3426950"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"818b4630-c5d5-5be6-be25-8ec52e1b23c9","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -شرب املسكر -تعاطي احلشيش املخدر -قيادة السيارة حتت تأثير املسكر إقرار -حد املسكر -التعزير باملنع من السفر .","document_number":"34270925","case_number":"34213894","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/17","year":"1434","subject":"مخدرات -تعاطي مخدرات -شرب املسكر -تعاطي احلشيش املخدر -قيادة السيارة حتت تأثير املسكر إقرار -حد املسكر -التعزير باملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34270925 :‬تاريخه ‪1434/07/17 :‬هـ‬\n                    ‫رقم الدعوى‪34213894 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n    ‫‪               34322429‬تاريخه‪1434/9/20:‬هـ‬\n\n\n\n‫مخدرات ‪ -‬تعاطي مخدرات ‪ُ -‬شــرب املســكر ‪ -‬تعاطي احلشــيش املُخدر‬\n‫‪ -‬قيــادة الســيارة حتــت تأثيــر املُســكر ــإقرار ‪ -‬حــد املســكر ‪ -‬التعزيــر‬\n                                                          ‫باملنــع مــن الســفر ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه صلــى اهلل عليــه وســلم « مــن شــرب اخلمــر فــا جلــدوه »‪ .‬أخرجه‬\n                                               ‫أحمد وأبو داود والنســائي ‪.‬‬\n‫‪ -2‬فعــل عمــر ـ رضــي اهلل عنــه ـ مبحضــر املهاجريــن واألنصــار بجلــد‬\n                                                 ‫الســكران ثمانــن جلــدة ‪.‬‬\n                                                   ‫‪ -3‬املرء مؤاخذ بإقراره ‪.‬‬\n‫‪ -4‬قــال ابــن حجــر يف فتــح البــاري (‪ « : )45/10‬واســتدل مبطلــق قولــه‬\n‫صلــى اهلل عليــه وســلم « كل ُمســكر حــرام » علــى حتــرمي مــا ُيســكر ولــو‬\n‫لــم يكــن شــراب ًا فيدخــل يف ذلــك احلشيشــة وغيرهــا وقــد جــزم النــووي‬\n                                                     ‫وغيــره بأنهــا ُمســكرة » ‪.‬‬\n‫‪ -5‬مــا ذكــره أهــل العلــم ( مــن أنــه إذا اجتمعــت حــدود مــن جنــس‬\n‫واحــد قبــل إقامــة احلــد تداخلــت وكفــاه حــد واحــد ) كشــاف القنــاع‬\n                                                                      ‫(‪.)29/14‬‬\n‫‪ -6‬املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الفقــرة‬\n                                                                            ‫(‪.)1‬‬\n             ‫‪ -7‬املادة (‪ )3‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                                                                                    ‫‪128‬‬\n\f                    ‫‪ -8‬القاعدة القانونية (ال عقوبة وال جرمية إ َّال بنص ) ‪.‬‬\n      ‫‪ -9‬املــادة (‪ )30‬مــن الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة والتــي جعلــت للقاضــي ســلطة تقديريــة لســجن‬\n                                                                 ‫املتعاطــي ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب ا ُملســكر وتعاطــي‬\n      ‫احلشــيش وقيــادة الســيارة حتــت تأثيــر ا ُملســكر ومــادة احلشــيش و طلــب‬\n      ‫املدعــي العــام احلكــم عليــه بحد املســكر ‪ ،‬وســجن املدعــى عليه ومنعه‬\n      ‫مــن الســفر بنــاء علــى املــواد (  ‪ ) 56/ 41‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثرات العقلية ‪ ،‬حيث أنه مت القبض على املدعى عليه إثر ممارســة‬\n      ‫التفحيــط وبعثــت عينــة مــن ســوائله أثبــت التقريــر الكيمائــي إيجابيــة‬\n      ‫العينــة ملركبــات احلشــيش املخــدرة والكحول‪،‬كمــا أقــر املدعــى‬\n      ‫عليــه بشــربه ا ُملســكر وتعاطيــه احلشــيش وأنكــر قيــادة الســيارة حتــت‬\n      ‫تأثيــر ا ُملســكر واحلشــيش ‪ ،‬وبنــاء علــى ماتقــدم حكمــت احملكمــة‬\n      ‫علــى املدعــى عليــه بحــد ا ُملســكر ‪ -‬منعــه مــن الســفر ملــدة ســنتني خــارج‬\n      ‫اململكــة وصــرف النظــر عــن تطبيــق املــادة (‪ )41‬مــن نظــام املخــدرات‬\n      ‫واملؤثــرات العقليــة ‪،‬حيــث أنــه لــم يثبــت لــدى احملكمــة قيــادة املدعــى‬\n      ‫عليــه الســيارة حتــت تأثيــر ا ُملســكر واحلشــيش وقنــع املدعــى عليــه‬\n      ‫باحلكــم وأبــدى املدعــي العــام اعتراضــه علــى احلكــم بــدون الئحــة‬\n                        ‫اعتراضيــة وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪129‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق  ‪1434/ 7 /17‬ه ـ لــدي‬\n‫أنــا القاضــي باحملكمــة اجلزائيــة بالدمــام وبنــاء علــى املعاملــة احملالــة‬\n‫إلينــا مــن رئيــس احملكمــة برقــم (‪ )....‬وتاريــخ ‪1434/ 5 /8‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر‪ .......... /‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫رقــم (‪ ).......‬وقــدم املدعــي العــام الئحــة اإلدعــاء املتضمنــة بصفتي مدعي ًا‬\n‫عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة باملنطقــة الشــرقية أدعــي علــى‬\n‫املذكــور أعــاه باالطــاع علــى خطــاب مديــر مــرور الدمــام رقــم (‪).......‬‬\n‫وتاريــخ ‪ 1434/3/18‬املتضمــن انــه بيــوم اجلمعــة املوافــق ‪1434/2/22‬ه ـ‬\n‫ويف متــام الســاعة (‪ )4:15‬ص ‪ ،‬وقــع حــادث صــدم (عولــج مــن قبــل جهــة‬\n‫االختصــاص) بحــي بــن ســيارة مــن نــوع ‪ .......‬حتمــل الرقــم (‪)..........‬‬\n‫بقيــادة املتهــم ‪ /‬وبــن جســم ثابــت عبــارة عــن عمــود تابــع لشــركة‬\n‫االتصــاالت وذلــك بســبب ممارســة املتهــم ( للتفحيــط ) وببعــث عينــة مــن‬\n‫ســوائله ( الــدم والبــول ) ورد تقريــر املركــز اإلقليمــي ملراقبــة الســموم‬\n‫الشــرعية رقــم (‪ )..........‬وتاريــخ ‪1434/2/25‬ه ـ متضمنــا ايجابيــة‬\n‫العينــات املأخــوذة منــه ملركبــات احلشــيش املخــدر املــدرج باجلــدول األول‬\n‫فئــة ( أ ) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وايجابيتــه‬\n‫ملــادة الكحــول االيثيلــي وبنــاء علــى التقريــر الكيمــاوي مت القبــض‬\n‫عليــه بتاريخ‪1434/3/18‬ه ـ بســماع أقــوال املتهــم األوليــة مــن قبــل شــعبة‬\n‫مكافحــة املخــدرات بالدمــام أقــر بشــربه للمســكر وبتعاطيــه ملــادة‬\n‫احلشــيش املخــدر وانــه يتعاطــى احلشــيش منــذ أربعــة أشــهر وأخــر مــرة‬\n‫تعاطــى فيهــا كانــت قبــل احلــادث بأربعــة  أســابيع قــد انتهــى التحقيــق‬\n\n                                                                                       ‫‪130‬‬\n\f      ‫إلــى اتهــام‪ ........../‬باالتــي‪-1 :‬شــرب املســكر ‪-2‬تعاطيــه للحشــيش‬\n      ‫‪-3‬قيــادة الســيارة حتــت تأثيــر املســكر ومــادة احلشــيش وذلــك لألدلــة‬\n      ‫والقرائــن التاليــة ‪ -1 :‬اعترافــه مبــا نــوه عنــه املــدون علــى الصفحــة رقــم‬\n      ‫(‪ )2‬مــن ملــف التحقيــق املرفــق علــى اللفــة رقــم (‪ -2 )1‬تقريــر املركــز‬\n      ‫اإلقليمــي ملراقبــة الســموم الشــرعية املنــوه عنــه واملرفــق علــى اللفــة‬\n      ‫رقــم (‪ )2‬وحيــث إن مــا أقــدم عليــه املتهــم املذكــور ‪ -‬وهــو بكامــل‬\n      ‫أهليتــه املعتبــرة شــرعا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا‬\n      ‫أطلــب اآلتــي‪ :‬أوال‪ :‬احلكــم عليــه بحــد الســكر لقــاء شــربه للمســكر‬\n      ‫ثانيــا‪ :‬إثبــات مــا أســند إليــه مــن تعاطــي احلشــيش املخــدر وفق ـ ًا للفقــرة‬\n      ‫رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة ووفــق املــادة (‪ )30‬مــن الالئحــة التنفيذيــة واحلكــم عليــه مبــا‬\n      ‫يلــي‪ -1 :‬بعقوبــة الســجن الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪)41‬‬\n      ‫مــن النظــام ‪ -2‬منعــه مــن الســفر وفق ـ ًا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n      ‫(‪ )56‬مــن النظــام ثالثــا‪ :‬إثبــات قيادتــه للســيارة حتــت تأثيــر املســكر‬\n      ‫واحلشــيش املخــدر وفقــا للفقــرة رقــم (‪ )8‬مــن اجلــدول رقــم (‪ )1‬امللحــق‬\n      ‫بنظــام املــرور وإفهامــه أن عقوبتــه الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n      ‫رقــم (‪ )68‬مــن نظــام املــرور تقــرر مــن اجلهــة املختصــة وفــق الفقــرة (‪)2‬‬\n      ‫مــن قــرار مجلــس الــوزراء رقــم (‪ )315‬يف ‪1429/10/24‬هــ  وبــاهلل‬\n      ‫التوفيــق وبســؤال املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام‬\n      ‫مــن شــرب املســكر وتعاطــي احلشــيش املخــدر فهــذا صحيــح أمــا مــا‬\n      ‫ذكــره مــن قيــادة الســيارة حتــت تأثيرهمــا فهــذا غيــر صحيــح  ألننــي لــم‬\n      ‫أكــن أقــود الســيارة حــن وقــوع احلــادث وإمنــا كنــت راكبـ ًا يف الســيارة‬\n      ‫والــذي كان يقودهــا أحــد زمالئــي هــذه إجابتــي وبعــد تدويــن مــا ســبق‬\n\n\n‫‪131‬‬\n\f‫جــرى االطــاع علــى جميــع أوراق املعاملــة ومنهــا أقــوال املدعــى عليــه‬\n‫املدونــة علــى الصفحــة الثانيــة مــن ملــف التحقيــق فوجــدت فيهــا اعترافـ ًا‬\n‫مــن املدعــى عليــه بشــرب املســكر وتعاطــي احلشــيش املخــدر ولكــن لــم‬\n‫أجــد فيهــا اعترافـ ًا بقيــادة الســيارة حتــت تأثيرهمــا كمــا جــرى االطالع‬\n‫علــى خطــاب مديــر مــرور الدمــام املوجــه إلــى مديــر إدارة مكافحــة‬\n‫املخــدرات بالدمــام برقــم (‪ )......‬وتاريــخ ‪1434/3/18‬ه ـ املتضمــن أن‬\n‫الســيارة حــن وقــوع احلــادث كانــت بقيــادة املدعــى عليــه وجــرى البحــث‬\n‫يف املعاملــة عــن أي أوراق تخــص احلــادث وكيفيــة وقوعــه واألشــخاص‬\n‫املتواجديــن يف الســيارة حينــذاك فلــم أجــد شــيئ ًا مــن ذلــك كمــا أنــه ال‬\n‫يوجــد حتقيــق مــع املدعــى عليــه يف هيئــة التحقيــق واالدعــاء العــام  ولــم‬\n‫أجــد أي جهــد مبــذول مــن احملقــق للتأكــد مــن صحــة مــا يدعيــه املدعــى‬\n‫عليــه مــن أنــه لــم يكــن يقــود الســيارة حتــت تأثيــر املســكر واحلشــيش‬\n                                                              ‫املخــدر مــن عدمــه‬\n‫ولــم أجــد أي حتقيــق مــع املواطــن للتأكــد مــن صحــة ادعــاء املدعــى‬\n‫عليــه ثــم جــرى االطــاع علــى صحيفــة الســوابق املرفقــة باملعاملــة‬\n‫واملتضمنــة عــدم وجــود ســوابق مســجلة املدعــى عليــه فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه بشــرب املســكر‬\n‫وتعاطــي احلشــيش املخــدر واملــرء مؤاخــذ بإقــراره ولقولــه صلــى اهلل عليــه‬\n‫وســلم»من شــرب اخلمــر فاجلدوه»أخرجــه أحمــد وأبــو داود والنســائي‬\n‫وألن عمر‪-‬رضــي اهلل عنه‪-‬جلــد يف حــد اخلمــر ثمانــن جلــدة وكان‬\n‫ذلــك مبحضــر مــن املهاجريــن واألنصار‪-‬رضــي اهلل عنهم‪-‬فلــم ينكــره‬\n‫أحــد منهــم وبنــاء علــى مانــص عليــه أهــل العلــم مــن إقامــة حــد املســكر‬\n‫علــى متنــاول احلشــيش قــال ابــن حجــر يف فتــح الباري(‪ »)45/10‬و ُأســتدل‬\n\n\n                                                                                     ‫‪132‬‬\n\f       ‫مبطلــق قولــه صلــى اهلل عليــه وســلم «كل مســكر حــرام» علــى حتــرمي‬\n       ‫مايســكر ولــو لــم يكــن شــراب ًا فيدخــل يف ذلــك احلشيشــة وغيرهــا وقــد‬\n       ‫جــزم النــووي وغيــره بأنهــا مســكرة» وبنــاء علــى مانــص عليــه أهــل العلــم‬\n       ‫مــن أنــه إذا اجتمعــت حــدود مــن جنــس واحــد قبــل إقامــة احلــد تداخلــت‬\n       ‫وكفــاه حــد واحــد (كشــاف القنــاع‪ )29/14‬واســتناد ًا للفقــرة الثانيــة‬\n       ‫مــن املــادة الثالثــة والفقــرة األولــى من املادة السادســة واخلمســن من نظام‬\n       ‫مكافحــة املخــدرات واملؤثــرات العقليــة وحيــث إنــه العقوبــة والجرميــة‬\n       ‫إال بنــص وحيــث إن العقوبــات الــواردة يف املــادة احلاديــة واألربعــن‬\n       ‫مــن نظــام مكافحــة املخــدرات ال تنطبــق علــى التعاطــي واالســتعمال‬\n       ‫بخــاف العقوبــة الــواردة يف املــادة السادســة واخلمســن مــن نفــس النظــام‬\n       ‫فتنطبــق عليــه وحيــث أن املــادة الثالثــن مــن الالئحــة التنفيذيــة لنظــام‬\n       ‫مكافحــة املخــدرات واملؤثــرات العقليــة والتــي تنــص علــى مايلــي إذا‬\n       ‫رأى القاضــي تعزيــر املتعاطــي أو املســتعمل للمــواد املخــدرة أو املؤثــرات‬\n       ‫العقليــة بالســجن‪ ،‬فــا تتجــاوز العقوبــة احلــد األعلــى املنصــوص عليهــا‬\n       ‫يف الفقــرة (‪ )1‬مــن املــادة (احلاديــة واألربعــن) قــد تركــت موضوع ســجن‬\n       ‫املتعاطــي للمخــدرات مســألة اختياريــة وســلطة تقديريــة للقاضــي وحيــث‬\n       ‫إنــه التوجــد ســوابق مســجلة علــى املدعــى عليــه وحيــث إنــه يوجــد نقــص‬\n       ‫يف التحقيــق وال توجــد أدلــة كافيــة تثبــت قيــام املدعــى عليــه بقيــادة‬\n       ‫الســيارة حتــت تأثيــر املســكر واحلشــيش املخدر والحتمــال صحة مادفع‬\n      ‫بــه املدعــى عليــه مــن كــون أحد زمالئه هو من كان يقود الســيارة حني ‬\n       ‫وقــوع احلــادث لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه بشــرب املســكر‬\n       ‫وتعاطــي احلشــيش املخــدر وحكمــت عليــه لقــاء ذلــك مبــا يلــي ‪ /1‬جلــده‬\n       ‫حــد املســكر ثمانــن جلــدة ‪ /2‬منعــه مــن الســفر خــارج اململكــة مــدة‬\n\n\n‫‪133‬‬\n\f‫ســنتني تبــدأ مــن حــن اكتســاب احلكــم للقطعيــة‪ /3‬صرفــت النظــر‬\n‫عــن طلــب املدعــي العــام إيقــاع العقوبــة املنصــوص عليهــا يف املــادة احلاديــة‬\n‫واألربعــن مــن نظــام مكافحــة املخــدرات علــى املدعــى عليه‪/4‬لــم يثبــت‬\n‫لــدي إدانــة املدعــى عليــه قيــادة الســيارة حتــت تأثيــر املســكر واحلشــيش‬\n‫املخــدر لعــدم كفايــة األدلــة وبعــرض احلكــم علــى املدعــى عليــه قــرر‬\n‫القناعــة بــه وقــرر املدعــي العــام االعتــراض بالئحــة فأجيــب لطلبــه ومت‬\n‫تســليمه نســخة مــن احلكــم وأفهــم بتقــدمي االعتــراض عليــه خــال مهلــة‬\n‫ثالثــن يومــا وأنــه إذا انتهــت هــذه املهلــة ولــم يتقــدم باعتراضــه ســقط‬\n‫حقــه يف ذلــك وســوف يتــم رفــع احلكــم إلــى محكمــة االســتئناف بــدون‬\n‫الئحــة اعتراضيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وبــه‬\n                                                        ‫حــرر يف ‪1434/7/17‬هــ‪.‬‬\n‫ويف يــوم الثالثــاء املوافــق ‪1434/11/4‬ه ـ افتتحــت اجللســة الســاعة‬\n‫الواحــدة وقــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم (‪)..........‬‬\n‫وتاريــخ ‪1434/10/28‬هــ  املتعلقــة بدعــوى املدعــي العــام ضــد ‪........../‬‬\n‫وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم (‪)..........‬‬\n‫وتاريــخ ‪1434/9/20‬ه ـ املتضمــن املصادقــة علــى احلكــم لــذا جــرى‬\n‫إحلــاق ذلــك حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                   ‫وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n\n\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n‫املقيــدة لــدى احملكمــة برقــم وتاريــخ ‪1434/09/10‬ه ـ الــواردة مــن‬\n‫فضيلــة‪ ........../‬رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم  وتاريــخ‬\n\n\n                                                                                         ‫‪134‬‬\n\f      ‫‪1434/08/28‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪ ........../‬املســجل برقــم وتاريــخ ‪1434/07/17‬ه ـ‬\n      ‫اخلــاص بدعوى‪/‬املدعــي العــام   ضــد‪ /‬يف قضيــة مخــدرات   وقــد‬\n      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه  وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n      ‫‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                             ‫يف‪1434/09/17‬هــ‪.‬‬\n\n\n\n\n‫‪135‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":128,"source_page_end":135,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1853860ba4e1da4c0f53189acdb1791c99526c5233e5785f8ba8e2c9dbf27d79","normalized_text_hash":"255a9b624fb15757d72375623c4ac2d01eba5f19505c12f0811562740b34e1c3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p128-34270925"},{"id":"f5663bcd-4deb-5611-aed8-1ec8028cc600","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -التعدي على رجل أمن -ابتاع حبوب محظورة -التعزير بالسجن واجللد واملنع من السفر -1املادة ( )41من نظام مكافحة املخدرات واملؤثرات العقلية .","document_number":"34234754","case_number":"34227885","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/07","year":"1434","subject":"مخدرات -تعاطي مخدرات -التعدي على رجل أمن -ابتاع حبوب محظورة -التعزير بالسجن واجللد واملنع من السفر -1املادة ( )41من نظام مكافحة املخدرات واملؤثرات العقلية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34234754 :‬تاريخه‪1434/06/07 :‬هـ‬\n                    ‫رقم الدعوى‪34227885 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪     34281893‬تاريخه‪1434/7/29 :‬هـ‬\n\n\n\n‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬التعــدي علــى رجــل أمــن ‪ -‬ابتــاع حبــوب‬\n                ‫محظــورة ‪ -‬التعزيــر بالســجن واجللــد واملنــع من الســفر‬\n\n\n\n\n          ‫‪ -1‬املادة (‪ )41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n          ‫‪ -2‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بابتــاع احلبــوب احملظــورة ‪،‬‬\n  ‫ومقاومــة رجــال األمــن وطلــب املدعــي العــام ســجن املدعــى عليــه ومنعــه‬\n  ‫مــن الســفر بنــاء علــى املــواد (‪ )41‬و (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n  ‫واملؤثــرات العقليــة لقــاء ابتــاع احلبــوب املخــدرة وتعزيــره لقــاء التعــدي‬\n‫علــى رجــل االمــن‪ ،‬حيــث أنــه أثنــاء قيــام فرقــة مكافحــة املخــدرات  ‬\n  ‫بعملهــا شــوهدت ســيارة بقيــادة  املدعــى عليــه  ‪ ،‬لوحــظ عليــه عالمــات‬\n  ‫اخلــوف و اإلرتبــاك ‪ ،‬فتــم القبــض عليــه ‪ ،‬فقــام بدفــع رجــل األمــن وقــام‬\n  ‫بابتــاع شــي مــا بســرعة يشــتبه أن يكــون مــن احلبــوب احملظــورة ‪،‬‬\n  ‫وبتفتيشــه ‪ ،‬وبتفتيــش الســيارة لــم يعثــر علــى شــي  ‪  ،‬وبتحليــل عينــة‬\n  ‫املدعــى عليــه تبــن احتوائهــا علــى مــادة اإلمفيتامــن ‪ ،‬أنكــر املدعــى‬\n  ‫ا وطلــب القاضــي مــن املدعــي‬   ‫عليــه مــا جــاء يف الدعــوى جملــة وتفصيـ ً‬\n\n                                                                                      ‫‪136‬‬\n\f        ‫العــام إحضــار بينتــه ‪ ،‬وقــد شــهد الشــهود بــأن املدعــى عليــه قــام بابتــاع‬\n        ‫شــيء كان معــه يشــتبه أن تكــون مــن احلبــوب احملظــورة ‪ ،‬وقــد عدلــت‬\n        ‫البينــة حســب األصــول الشــرعية ووبنــاء علــى ماتقــدم فقــد حكمــت‬\n      ‫احملكمــة بجلــد املدعــى عليــه تعزيــر ًا لقــاء مقاومتــه لرجــال األمــن ‪  ،‬‬\n        ‫وتكــرار ســوابقه ‪  ،‬وابتالعــه للحبــوب احملظــورة و لــم يقتنــع املدعــي‬\n        ‫العــام باحلكــم وطلــب اســتئنافه بــدون الئحــة ‪ ،‬وأمــا املدعــى عليــه فقــد‬\n        ‫اعتــرض بالئحــة اعتراضيــه وصــدق احلكــم مــن محكمــة االســتئناف  ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا   القاضــي يف احملكمــة العامــة بعرعـر   ‬\n         ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بعرعــر برقــم  وتاريــخ ‪ 1434/05/18‬هــ  املقيــدة باحملكمــة برق ـم  ‬\n         ‫وتاريــخ ‪ 1434/05/18‬هــ  ففــي يــوم  الثالثــاء املوافــق‪1434/05/21‬‬\n         ‫ه ـ افتتحــت اجللســة الســاعة ‪   11 : 15‬وفيهــا حضــر املدعــي العــام‬\n         ‫وادعــى قائــا  ‪ :‬بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة‬\n         ‫مبنطقــة احلــدود الشــمالية أدعــي علــى ‪ /‬ســعودي اجلنســية مبوجــب‬\n         ‫الســجل املدنــي رقــم  فأنــه بتاريخ‪1434/3/27‬هــ  وأثنــاء قيــام فرقــة‬\n         ‫مكافحــة املخــدرات بعملهــا املعتــاد وذلــك مبســح األماكــن املشــبوهة‬\n         ‫مــن مروجــي ومســتخدمي املخــدرات‪  ،‬وعنــد الســاعة الثانيــة عشــر‬\n         ‫والربــع (‪ )12,15‬لي ـاً   شــوهدت ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة‬\n         ‫رقــم (‪ )..........‬متوقفــه عنــد احــد األماكــن املشــبوهة يف حــي العزيزيــة‬\n         ‫ويوجــد بهــا احــد األشــخاص وكانــت الســيارة مطفــأه و لوحــظ علــى‬\n         ‫الشــخص الــذي بدخلهــا اخلــوف واالرتبــاك فتــم القبــض عليــه وإنزالــه‬\n\n‫‪137‬‬\n\f  ‫مــن الســيارة ‪ ،‬فقــام املتهــم بدفــع رجــل األمــن وقــام بابتــاع شــيء مــا‬\n  ‫بســرعه يشــتبه أن يكــون مــن احلبــوب احملظــورة‪ ،‬وبتفتيشــه وتفتيــش‬\n  ‫ســيارته لــم يعثــر علــى أي شــيء مــن املمنوعــات  ‪  ،‬وبنــا علــى مــا قــام بــه‬\n  ‫مت اصطحــاب املتهــم إلدارة مكافحــة املخــدرات ومت إيداعــه التوقيــف‬\n  ‫يف حينــه  وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز‬\n‫الســموم بتبــوك رقــم لعــام ‪1434‬ه ـ إيجابيــة عينــة بول املتهــم لالمفيتامني ‬\n  ‫املنبــه للجهــاز العصبــي وهــو مــن املؤثــرات العقليــة اخلاضعــة للرقابــة‬\n  ‫واملنــوه عنــه باجلــدول الثانــي فئــة (ب) يف تعميــم صاحــب الســمو امللكــي‬\n‫وزيــر الداخليــة رقــم وتاريخ‪1426/10/25‬هــ‪ .‬وقــد انتهــى التحقيــق إلــى  ‬\n  ‫اتهــام‪ ، /‬بابتــاع احلبــوب احملضــوره احملتويــة علــى مــادة اإلمفيتامــن‬\n  ‫املنبهــة للجهــاز العصبــي ‪،‬املجــرم نظامــا بنــص املــادة الثالثــة مــن نظــام‬\n  ‫مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬الصــادر باملرســوم امللكــي‬\n  ‫رقــم  وتاريــخ ‪1426/7/8‬هــ‪ ،‬وقيامــه بدفــع رجــال األمــن ‪.‬وذلــك لألدلــة‬\n  ‫والقرائــن التاليــة ‪ -1 :‬مــا جــاء مبحضــر القبــض املرفــق املــدون علــى‬\n  ‫الصفحــة رقــم (‪) 13,12‬لفــة رقــم (‪ -2.)1‬مــا جــاء بالتقريــر الكيميائــي‬\n  ‫الشــرعي املرفــق لفــة رقــم (‪ .)27‬وحيــث أن مــا أقــدم عليــه املتهــم وهــو‬\n  ‫بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرعا‬\n  ‫ومجــرم نظامــا بنــص املــادة الثالثــة مــن نظــام مكافحــة املخــدرات‬\n  ‫واملؤثــرات العقليــة ‪ ،‬الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ‬\n  ‫‪1426/7/8‬ه ـ لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n                                                                             ‫مبــا يلــي‪:‬‬\n  ‫‪-1‬عقوبــة الســجن وفقــا للفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n  ‫مكافحــة املخــدرات واملؤثــرات العقليــة واملــادة (‪ )30‬مــن الئحتــه‬\n\n\n                                                                                            ‫‪138‬‬\n\f      ‫التنفيذية‪-2.‬عقوبــة املنــع مــن الســفر خــارج اململكــة وفقا للفقــرة األولى‬\n      ‫مــن املــادة (‪ )56‬مــن النظــام نفســه ‪ -3‬عقوبــة تعزيريــة لقــاء قيامــه بدفــع‬\n      ‫رجــل األمــن وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه احلاضــر‬\n      ‫انكــر مــا جــاء بهــا جملــة وتفصيــا وبســؤال املدعــي العــام البينــة‬\n      ‫علــى الدعــوى فأجــاب قائــا‪ :‬بينتــي ماجــاء مبحضــر القبــض املرفــق‬\n      ‫لكــم ومــن اعــده شــهود عليــه واطلــب مهلــة الحضارهــم ولتمكــن‬\n      ‫املدعــي العــام مــن ذلــك جــرى رفــع اجللســة وعليــه حصــل التوقيــع‪ .‬وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫حــرر يف  ‪ 1434/05/21‬ه ـ احلمــد هلل وحــده وبعــد  ففــي يــوم  اإلثنــن‬\n      ‫املوافــق‪ 1434/05/27‬ه ـ افتتحــت اجللســة الســاعة  ‪ 10.45‬وفيهــا حضر‬\n      ‫املدعــي العــام وحضــر حلضــوره املدعــى عليــه املثبــت هويتهمــا ســابقا وقد‬\n      ‫احضــر املدعــي العــام لشــهاده كال مــن  ســجل مدنــي رقــم  وقــد قــال‬\n      ‫معرفــا اننــي اعمــل مبكافحــة املخــدرات بعرعــر برتبــة جنــدي وابلــغ مــن‬\n      ‫العمــر (‪ )29‬عــام واســكن مبدينــة عرعــر وليــس لــي معرفــه باملدعــى‬\n      ‫عليــه و ســجل مدنــي رقــم  وقــد قــال معرفــا اننــي اعمــل مبكافحــة‬\n      ‫املخــدرات بعرعــر برتبــة جنــدي وابلــغ مــن العمــر (‪ )22‬عــام واســكن‬\n      ‫مبدينــة عرعــر وليــس لــي معرفــه باملدعــى عليــه ولــدى استشــهادهما‬\n      ‫شــهد كل واحــد منهمــا مبفــرده فأنــه بتاريــخ ‪1434/3/27‬هــ  وأثنــاء‬\n      ‫قيامنــا بعملنــا املعتــاد وذلــك مبســح األماكــن املشــبوهة مــن مروجــي‬\n      ‫ومســتخدمي املخــدرات‪  ،‬وعنــد الســاعه الثانيــة عشــر والربــع (‪)12,15‬‬\n      ‫لي ـاً  شــاهدنا ســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة رقــم () متوقفــه عنــد‬\n      ‫احــد االماكــن املشــبوهه يف حــي العزيزيــة ويوجــد بهــا أحــد األشــخاص‬\n      ‫وكانــت الســيارة مطفــأه و لوحــظ علــى الشــخص الــذي بدخلهــا اخلــوف‬\n\n\n‫‪139‬‬\n\f ‫واإلرتبــاك فتــم القبــض عليــه وإنزالــه مــن الســيارة وهــو ذات الشــخص‬\n ‫املاثــل امامنــا  فقــام املتهــم بدفعنــا وقــام ببتــاع شــيء مــا بســرعة يشــتبه‬\n ‫أن يكــون مــن احلبــوب احملظــورة‪ ،‬وبتفتيشــه وتفتيــش ســيارته لــم يعثــر‬\n ‫علــى أي شــيء مــن املمنوعــات ‪  ،‬وبنــا علــى مــا قــام بــه مت إصطحــاب‬\n ‫املتهــم الدارة مكافحــة املخــدرات وقــد قــاوم ورفــض الركــوب يف‬\n ‫الدوريــة هكــذا شــهدا وبعــرض ذلــك علــى املدعــى عليــه أصــر علــى‬\n ‫إنــكاره وبســؤاله هــل لديــه طعــن بالشــهود أجــاب قائــا ال اعــرف احــد‬\n ‫منهــم وقــد جــرى تعديــل الشــهود مــن كال مــن و ولتأمــل ماجــرى ضبطــه‬\n ‫جــرى رفــع اجللســة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/05/27‬ه ـ‬\n ‫احلمــد هلل وحــده وبعــد  ففــي يــوم  األربعــاء املوافــق‪ 1434/06/07‬ه ـ‬\n ‫افتتحــت اجللســة الســاعة ‪ 11.30‬وفيهــا حضــر املدعــي العــام وحضــر‬\n ‫حلضــوره املدعــى عليــه واملثبــت هويتهــم ســابقا وبســؤال املدعــي‬\n ‫العــام هــل لديــه مزيــد بينــة أجــاب قائ ـاً‪ :‬ليــس لــدي ســوى ماقدمتــه‬\n ‫وقــد جــرى منــا االطــاع علــى التقريــر الكيميائــي رقــم (‪ )....‬وتاريــخ‬\n ‫‪1434/4/28‬ه ـ ونــص احلاجــة منــه ( وبإجــراء الفحــص الكميائــي‬\n ‫الشــرعي ثبــت إجابيــة عينــة البــول لإلمفيتامــن ) أ‪.‬ه ـ وذلــك علــى لفــه‬\n‫رقــم (‪ )27‬مــن طيــات املعاملــه وبســؤال املدعــى عليــه عــن الســابقتني ‬\n ‫املدونــة بســجله وهــي مخــدرات ومضاربــة صــادق عليهــا فبنــاء علــى‬\n ‫ماتقــدم مــن الدعــوى وإنــكار املدعــى عليــه ملــا جــاء فيهــا وقيــام البينــة‬\n ‫املعدلــه شــرعا علــى ماجــاء يف الدعــوى ونظــرا ملــا جــاء يف التقريــر‬\n ‫الكيميائــي املشــار إليــه بعاليــه فقــد ثبــت لــدي ادانــة املدعــى عليــه‬\n ‫بحيــازة وابتــاع حبــوب محظــوره محتويــه علــى مــادة االميتفامــن ونظــر‬\n\n\n                                                                                         ‫‪140‬‬\n\f      ‫لوجــود ســابقه مماثلــة علــى املدعــى عليــه ونظــر املقاومتــه لرجــال األمــن‬\n      ‫فقــد قــررت احلكــم عليــه مبايلــي ‪ :‬أوال ســجنه ملــدة ســتة اشــهر تبــدأ‬\n      ‫مــن تاريــخ أيقافــه املوافــق ‪1434/3/27‬ه ـ وذلــك بنــاء علــى املــادة (‪)41‬‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــه ثانيــا ‪ :‬جلــده مائــة‬\n      ‫وخمســن جلــده تعزيــرا علــى ثــاث دفعــات كل دفعــة خمســن ســوطا‬\n      ‫بــن كل دفعــة واألخــرى مااليقــل عــن شــهر ثالثــا‪ :‬منعــه مــن الســفر‬\n      ‫خــارج اململكــة بعــد إنتهــاء محكوميتــه وذلــك مــدة ســنتني بنــاء علــى‬\n      ‫املــادة (‪ )56‬مــن النظــام املشــار إليــه وبعــرض احلكــم علــى املدعــى عليــه‬\n      ‫قــرر أعتراضــه علــى احلكــم فأفهــم أن لــه ثالثــون يومــا مــن تاريــخ هــذا‬\n      ‫اليــوم ليقــدم فيهــا اعتراضــه وإالفــإن حقــه يف االعتــراض يســقط كمــا‬\n      ‫قــرر املدعــي العــام االعتــراض علــى احلكــم واكتفــى بالئحــة الدعــوى‬\n      ‫كالئحــة اعتراضيــة  وقــد جــرى تســليم املدعــى عليــه نســخة من احلكم‬\n      ‫يف هــذه اجللســة‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/06/07‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد  ففــي يــوم  اإلثنــن املوافــق‪ 1434/06/19‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 01.00‬ظهــرا  وفيهــا حضــر املدعــى عليــه‬\n      ‫واملثبــت هويتــه يف جلســة ماضيــة وقــد جــرى منــا اإلطــاع علــى الالئحــة‬\n      ‫األعتراضيــة املقدمــة منــه واملقيــدة بهــذه احملكمــة برقــم   وتاريــخ‬\n      ‫‪1434/6/19‬ه ـ واملكونــة مــن خطــاب وثــاث صفحــات فوجــدت يف‬\n      ‫الصفحــة الثانيــة منهــا كالم للمدعــى عليــه مضمونــة اننــي حكمــت‬\n      ‫علــى الفرقــة القابضــة بالســجن خمســة عشــر يــوم لشــهادة زور وبســؤال‬\n      ‫املدعــى عليــه عــن ذلــك أجــاب قائــا اننــي ســمعت ذلــك مــن أحــد‬\n      ‫الســجناء لــدى وال اعلــم صحتــه وأفهمتــه ان ذلــك غيــر صحيــح وان عليــه‬\n\n\n‫‪141‬‬\n\f‫االلتــزام بكتابــة ماهــو متأكــد منــه يف الئحتــه االعتراضيــة واســتعد‬\n‫بذلــك وتراجــع عــن ماهــو مكتــوب وبإطالعــي علــى باقــي الالئحــة لــم‬\n‫أجــد مايؤثــر علــى ماحكمــت بــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n  ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/06/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتمييز‬\n‫القضايــا اجلزائيــة  مبحكمــة االســتئناف باجلــوف علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمة العامــة بعرعــر برقموتاريخ‪1434/6/24‬ه ـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪ .... /‬املســجل‬\n‫برقمفــي‪1434/6/7‬ه اخلــاص بدعــوى املدعــي العــام ضــد‪ .... /‬يف قضيــة‬\n‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملة‪.‬تقــرر باألكثريــة‬\n‫املصادقــة علــى احلكــم‪.‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                              ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                       ‫‪142‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":136,"source_page_end":142,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bd222f5d116f361ac0bc5917e85d09e3e1aa833302d3ae5495c7dbd24923c91e","normalized_text_hash":"e0cdbb1fa122750a5dbe3643f3fc05c11cfb5f50ca35a2c3cb1fc6df1eb640ef","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p136-34234754"},{"id":"82eb55cd-0d13-5219-8bac-cb95a2ae2d1d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -تعاطي احلشيش املخدر -تعاطي احلبوب اإلمفيتامن احملظورة -التستر على مصدر املخدرات - إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير باملنع من السفر -رد طلب املدعي العام .","document_number":"34282605","case_number":"34234381","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/29","year":"1434","subject":"مخدرات -تعاطي مخدرات -تعاطي احلشيش املخدر -تعاطي احلبوب اإلمفيتامن احملظورة -التستر على مصدر املخدرات - إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير باملنع من السفر -رد طلب املدعي العام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34282605 :‬تاريخه ‪1434/07/29 :‬هـ  ‬\n                            ‫رقم الدعوى‪34234381 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                   ‫‪   34294349‬تاريخه‪1434/8/15 :‬هـ‬\n\n\n\n      ‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬تعاطــي‬\n      ‫احلبــوب اإلمفيتامــن احملظــورة ‪ -‬التســتر علــى مصــدر املخــدرات ‪-‬‬\n      ‫إقــرار ‪ -‬إقامــة حــد املســكر علــى متعاطــي احلشــيش ‪ -‬التعزيــر باملنــع‬\n                                       ‫مــن الســفر ‪ -‬رد طلــب املدعــي العــام ‪.‬‬\n\n\n\n\n                ‫‪ -1‬قول النبي صلى اهلل عليه وسلم ‪ ( :‬كل مسكر حرام ) ‪.‬‬\n                                         ‫‪ -2‬قاعدة ( املرء مؤاخذ بإقراره ) ‪.‬‬\n      ‫‪ -3‬مــا ذكــره أهــل العلــم مــن أن احلشــيش يشــترك مــع اخلمــر يف‬\n                                                          ‫منــاط احلكــم ‪.‬‬\n                      ‫‪ -4‬ما ذكره أهل العلم من تداخل احلدود والتعازير ‪.‬‬\n              ‫‪ -5‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بتعاطــي احلشــيش املخــدر‪  ،‬‬\n        ‫وحبــوب اإلمفيتامــن املنبهــة احملظــورة ‪  ،‬وتســتره على مصدر املخدرات‬\n      ‫وطلــب املدعــي العــام ســجن املدعــى عليــه ومنعــه مــن الســفر بنــاء علــى‬\n      ‫املادتــن (‪ )41‬و (‪ )56‬مــن نظــام مكافحــة املخــدرات ‪،‬حيــث قبــض على‬\n      ‫املدعــى عليــه يف قضيــة جنائيــة وبتحليــل عينــة مــن ســوائله أثبــت التقريــر‬\n\n‫‪143‬‬\n\f‫الكيميائــي إيجابيتهــا ملــادة احلشــيش املخــدر ‪ ،‬كمــا أقــر املدعــى عليــه‬\n‫بتعاطــي احلشــيش املخــدر ‪  ،‬وحبــوب اإلمفيتامــن املنبهــة احملظــورة ‪،‬‬\n‫وأنكــر التســتر علــى مصــدر املخــدرات وطلــب القاضــي مــن املدعــي‬\n‫العــام البينــة علــى تســتر املدعــى عليــه علــى مصــدر املخــدرات‪  ،‬فقــرر‬\n‫بأنــه ليــس لديــه ســوى مــا جــاء يف طيــات املعاملــة ‪ ،‬وبتصفحهــا لــم يجــد‬\n‫القاضــي بينــة علــى تســتر املدعــى عليــه علــى مصــدر املخــدرات ‪،‬بنــاء‬\n‫علــى ماتقــدم حكمــت احملكمــة علــى املدعــى عليــه بحــد املســكر‬\n‫وبتعزيــره مبنعــه مــن الســفر ملــدة ســنتني بعــد تنفيــذ محكوميتــه‪ ،‬ورد‬\n‫القاضــي طلــب املدعــي العــام تعزيــر املدعــى عليــه لقــاء تســتره علــى‬\n‫مصــدر املخــدرات‪ ،‬أقــر املدعــي العــام االعتــراض بالئحــة‪ ،‬وأمــا املدعى‬\n    ‫عليــه فقــد قنــع باحلكــم وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫اجلزائية باألحساء   ‬\n                 ‫ّ‬     ‫احلمد هلل وحده وبعد فلدي أنا القاضي يف احملكمة‬\n   ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة  رئيــس احملكمــة اجلزائيــة يف‬\n     ‫محافظــة األحســاء املكلــف برقــم ‪ 34234381‬وتاريــخ ‪1434/05/21‬‬\n‫هــ  املقيــدة باحملكمــة برقــم ‪ 341240046‬وتاريــخ ‪ 1434/05/21‬ه ـ  ‬\n        ‫ففــي يــوم  الســبت املوافــق ‪ 1434/07/29‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫‪ 11 : 15‬وفيهــا حضــر املدعــي العــام املعمــد بالترافع أمام هذه احملكمة‬\n     ‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n     ‫األحســاء ذي الرقــم  والتاريــخ ‪ 1433/12/01‬ه ـ وادعــى ضــد احلاضــر‬\n‫ا يف دعــواه     ‬‫معــه ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم  قائ ـ ً‬\n     ‫قبــض علــى املدعــى عليــه  أثــر ورود تقريــر الســموم الشــرعي رقــم (‪342‬‬\n\n                                                                                           ‫‪144‬‬\n\f      ‫م أ)لعام‪1434‬هـ   من شــرطة محافظة األحســاء على ذمه قضيه جنائية  ‬\n        ‫والــذي يفيــد بإيجابيــة عينــة البــول املرســلة   ملــادة احلشــيش املخــدر‬\n        ‫واملدرجــة مــن ضمــن املــواد احملظــورة يف اجلــدول رقــم (‪ )1‬فئــة (أ) مــن‬\n        ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املوافــق عليــه باملرســوم‬\n        ‫امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ  وملركبــات األمفيتامــن‬\n        ‫املنبــه احملظــور  واملدرجــة مــن ضمــن املــواد احملظــورة يف اجلــدول رقــم‬\n        ‫(‪ )2‬فئــة (ب) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املوافــق‬\n                      ‫عليــه باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪.‬‬\n        ‫بضبــط أقوالــه‪  /‬أقــر  بتعاطــي احلشــيش املخــدر واحلبــوب احملظــورة‪،‬‬\n            ‫وأفــاد بأنــه يحصــل علــى املخــدرات مــن شــخص كينــي ال يعرفــه ‪.‬‬\n        ‫وقــد اثبــت تقريــر الكيمــاوي الشــرعي رقــم (‪ 342‬م أ) لعــام ‪1434‬ه ـ‬\n        ‫إيجابيــة عينــة البــول املرســلة   ملــادة احلشــيش املخــدر  املــدرج يف اجلــدول‬\n        ‫األول فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪،‬‬\n        ‫وإيجابيــة عينــة البــول املرســلة   ملركــب اإلمفيتامــن  املــدرج يف اجلــدول‬\n        ‫الثانــي فئــة (ب) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪،‬‬\n        ‫وســلبية العينــات املرســلة للخمــر املســكر ‪ .‬وقــد أســفر التحقيــق عــن‬\n        ‫توجيــه االتهــام لــه بتعاطــي احلشــيش املخــدر و حبــوب اإلمفيتامــن‬\n        ‫املنبهــة احملظــورة املجرمــة يف ضــوء الفقــرة الثانيــة مــن املــادة الثالثــة‬\n        ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n        ‫امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪ ،‬وتســتره علــى‬\n                                                                     ‫مصــدر املخــدرات‪.‬‬\n                                                         ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n        ‫‪ -1‬إقــرار املدعــى عليــه املنــوه عنــه املــدون علــى الصفحــة رقــم (‪)3-2‬‬\n\n\n‫‪145‬‬\n\f                                                    ‫املرفــق علــى اللفــة رقــم (‪.)13‬‬\n             ‫‪ -2‬التقرير الكيميائي الشرعي املرفق على اللفة رقم (‪. )4‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور ـ وهــو بكامــل أهليتــه املعتبرة شــرع ًا‬\n‫ـ فعــل محــرم و مجــرم معاقــب عليــه شــرع ًا ونظامـ ًا لــذا اطلــب إثبــات مــا‬\n                                            ‫أســند إليــه واحلكــم عليــه مبــا يلــي ‪-:‬‬\n‫‪ .1‬مبعاقبتــه بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة ( ‪ ) 41‬مــن‬\n‫النظــام املشــار إليــه أعــاه ‪ ،‬و املــادة (‪ )30‬مــن الالئحــة التنفيذيــة لــذات‬\n               ‫النظــام املشــار اليــه أعــاه لقــاء مــا أســند إليهــم مــن اتهــام ‪.‬‬\n‫‪ .2‬معاقبتــه بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة ( ‪ ) 56‬مــن ذات‬\n                            ‫النظــام وذلــك مبنعــه مــن الســفر إلــى خــارج البــاد ‪.‬‬\n‫ال ما ذكــره املدعي العام‬      ‫هــذه دعــواي  وبســؤال املدعــى عليــه أجــاب قائ ً‬\n‫مــن أنــه قبــض علــي مــن قبــل دوريــات األمــن باألحســاء وأنــه مت حتليلــي‬\n‫وأنــه عثــر يف عينــة البــول املرســلة علــى مركبــات احلشــيش املخــدر‬\n‫ومركــب إمفيتامينــي احملظوريــن وأننــي أتعاطاهــا فهــذا كلــه صحيــح‬\n‫وأمــا مــا ذكــره املدعــي العــام مــن أننــي تســترت علــى مصــدر احلشــيش‬\n‫املخــدر واملخــدرات فهــذا كلــه غيــر صحيــح حيــث أننــي حصلــت عليهــا‬\n‫مــن شــخص كينــي هكــذا أجــاب وبســؤال املدعــي العــام هــل لديــه‬\n‫بينــة علــى أن املدعــى عليــه قــام بالتســتر علــى مصــدر  احلشــيش املخــدر‬\n‫ا ليــس لــدي ســوى مــا ذكرتــه يف أوراق املعاملــة‬          ‫واملخــدرات أجــاب قائـ ً‬\n‫هكــذا أجــاب وباإلطــاع علــى املعاملــة وجــد فيهــا علــى لفــة رقــم ‪13‬‬\n‫صحيفــة رقــم ‪ 3-2‬أقــوال املدعــى عليــه والتــي تتطابــق مــع مــا ذكــره‬\n‫املدعــى عليــه يف مجلــس احلكــم كمــا جــرى اإلطــاع علــى املعاملــة‬\n‫وجــد فيهــا علــى لفــة رقــم ‪ 4‬التقريــر الســموم الشــرعية رقــم ‪ 342‬م أ لعــام‬\n\n\n                                                                                           ‫‪146‬‬\n\f      ‫‪1434‬ه ـ واملتضمــن إيجابيــة العينات املرســلة ملركبات احلشــيش املخدر‬\n      ‫وملركــب أمفيتامينــي احملظوريــن ا‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة وإقــرار املدعــى عليــه وحيــث إن املــرء مؤاخــذ بإقــراره ولتقريــر‬\n      ‫الســموم الشــرعية ولقــول النبــي صلــى اهلل عليــه وســلم كل مســكر‬\n      ‫حــرام وحيــث إن احلشــيش يشــترك مــع اخلمــر يف منــاط احلكــم وحيــث‬\n      ‫إن احلــدود والتعازيــر تتداخــل لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى‬\n      ‫عليــه بتعاطــي احلشــيش املخــدر وحبــوب اإلمفيتامــن املنبــة احملظــورة‬\n      ‫ولــم يثبــت لــدي إدانــة املدعــى عليــه بتســتره علــى مصــدر احلشــيش‬\n      ‫املخــدر واملخــدرات وحكمــت عليــه مبــا يلــي ‪ :‬أو ًال ‪ :‬جلــد املدعــى عليــه‬\n      ‫ثمانــن جلــدة دفعــة واحــدة حــد املســكر ثانيـ ًا ‪ :‬رد دعــوى املدعــي العــام‬\n      ‫بخصــوص معاقبــة املدعــى عليــه بالعقوبــة الــواردة يف الفقــرة (‪ )1‬مــن‬\n      ‫املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لعــدم‬\n      ‫وجــود حيــازة ثالثـ ًا ‪ :‬منــع املدعــى عليــه مــن الســفر خــارج اململكــة مــدة‬\n      ‫ســنتني بعــد تنفيــذ محكوميتــه وذلــك مبوجــب املــادة ‪ 56‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة رابعـ ًا ‪ :‬رد دعــوى املدعــي العــام‬\n      ‫بخصــوص معاقبــة املدعــى عليــه لقــاء تســتره علــى مصــدر  احلشــيش‬\n      ‫املخــدر واملخــدرات لعــدم ثبوتهــا وبــه حكمــت وبعــرض الدعــوى علــى‬\n      ‫املدعــي العــام واملدعــى عليــه قــرر املدعــي العــام االعتــراض علــى احلكــم‬\n      ‫وطلــب رفــع املعاملــة إلــى محكمــة االســتئناف بــدون الئحــة فأجبتــه‬\n      ‫لطلبــه وأمــا املدعــى عليــه قــرر قناعتــه بــه وبــه ختمــت اجللســة يف متــام‬\n      ‫الســاعة العاشــرة والنصــف صباحاًوبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/07/29‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n\n\n‫‪147‬‬\n\f  ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n  ‫لــدى احملكمــة برقــم ‪/341980209‬ج‪ 2‬وتاريــخ ‪1434/8/15‬ه ـ‬\n  ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n  ‫املكلــف برقــم ‪ 34/1301126‬وتاريــخ ‪1434/8/9‬ه ـ املرفــق بهــا القــرار‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ /‬املســجل برقــم  ‬\n  ‫وتاريــخ ‪1434/7/29‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ /‬يف قضيــة‬\n  ‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n  ‫فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n  ‫علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                ‫وســلم‪ .‬حــرر يف‪1434/8/21‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                     ‫‪148‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":143,"source_page_end":148,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7bef03a9bdfd1dd358f6a1eb12edc87cc2abef691d95b1e6c45a9a09711c7cf3","normalized_text_hash":"10e3964272d90bbff60463f68e09a89f29e87029242041b5e076bab77d777455","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p143-34282605"},{"id":"d941b6bc-c9bd-5da1-a496-85d4792383e9","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -االشتباه يف تعاطي احلشيش املخدر -درء احلدود بالشبهات -إنكار -عدم وجود بينة -عدم ثبوت إدانة.","document_number":"34226530","case_number":"34246869","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/28","year":"1434","subject":"مخدرات -تعاطي مخدرات -االشتباه يف تعاطي احلشيش املخدر -درء احلدود بالشبهات -إنكار -عدم وجود بينة -عدم ثبوت إدانة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34226530 :‬تاريخه ‪1434/05/28 :‬هـ‬\n                          ‫رقم الدعوى‪34246869 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34253718‬تاريخه‪1434/6/27 :‬هـ‬\n\n\n\n      ‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬االشــتباه يف تعاطــي احلشــيش املخــدر‬\n      ‫‪ -‬درء احلــدود بالشــبهات ‪ -‬إنــكار ‪ -‬عــدم وجــود بينــة ‪ -‬عــدم ثبــوت إدانــة‪.‬‬\n\n\n\n\n                                                  ‫قاعدة ( احلدود تدرأ بالشبهات ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه باتهامــه بتعاطــي احلشــيش‬\n      ‫املخــدر ‪  ،‬اثــر توقيفــه بإصالحيــة احلائــر علــى ذمــة قضيــه أخــرى وطلــب‬\n      ‫املدعــي العــام احلكــم علــى املدعــى عليــه بالتعزيــر بالســجن واملنــع مــن‬\n      ‫الســفر وبتشــديد العقوبــة لقــاء كثــرة ســوابقه وإقامــة حــد املســكر‬\n      ‫عليــه‪  -‬حيــث مت االشــتباه مبجموعــة مــن الســجناء يف إصالحيــة احلائــر‬\n      ‫بتعاطــي املخــدرات ‪ ،‬ومت إرســال املدعــى عليــه للمركــز الصحــي ‪،‬‬\n      ‫ألخــذ عينــة منــه ‪ ،‬وإرســالها للتحليــل ‪ ،‬وقــد أثبــت التقريــر الكيمائــي‬\n      ‫إيجابيــة العينــة للمــادة الفعالــة للحشــيش املخــدر ‪  -‬أنكــر املدعــى عليــه‬\n      ‫مــا جــاء يف دعــوى املدعــي العــام وبطلــب البينــة مــن املدعــي العــام قــرر‬\n      ‫أنــه ليــس لديــه ســوى مــا قدمــه يف أوراق القضيــة‪  ،‬لــم يجــد القاضــي‬\n      ‫إ َّال حتليـ ًـا داخــل الســجن ‪ ،‬وأفــاد املدعــى عليــه بأنــه قــد يكــون شــم‬\n      ‫احلشــيش ‪ ،‬داخــل الســجن‪ ،‬اثــر اختالطــه مــع أنــاس بعضهــم يتعاطــى‬\n\n‫‪149‬‬\n\f‫احلشــيش ‪ ،‬كونــه ســجني معهــم و لــم يثبــت املدعــي العــام مــا جــاء يف‬\n‫دعــواه‪ ،‬وبنــاء علــى ماتقــدم حكمــت احملكمــة بصــرف النظــر عــن‬\n‫مطالبتــه بحــد املســكر ‪  ،‬وغيــره ‪  ،‬بحــق املدعــى عليــه ـ ـ وقــرر املدعــي‬\n‫العــام اعتراضــه بــدون الئحــة ‪  ،‬واملدعــى عليــه قــرر القناعــة باحلكــم و‬\n                                  ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا القاضي يف احملكمة اجلزائية بالرياض   ‬\n   ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n   ‫بالريــاض برقــم  وتاريــخ ‪ 1434/05/28‬هــ  املقيــدة باحملكمــة برقــم‬\n   ‫وتاريــخ ‪ 1434/05/28‬هــ  ففــي يــوم  الثالثــاء املوافــق‪ 1434/05/28‬ه ـ‬\n   ‫افتتحــت اجللســة الســاعة ‪  11 : 15‬وفيهــا قــدم املدعــي العــام دعــواه ضــد‬\n   ‫‪ ....../‬البالــغ مــن العمــر (‪ )38‬عام ـ ًا ســعودي بالهويــة رقــم (‪ )....‬أعــزب‬\n   ‫موظــف حكومــي متعلــم يقيــم مبحافظــة املجمعــة ‪ ،‬موقــوف بتاريــخ‬\n   ‫‪1427/11/05‬ه ـ لــدى إصالحيــة احلائــر علــى ذمــة قضيــة طعــن مبوجــب‬\n   ‫مذكــرة توقيــف رقــم (‪ )....‬وتاريــخ ‪1427/11/08‬ه ـ ‪ .‬حيــث إنــه بتاريــخ‬\n   ‫‪1432/08/25‬ه ـ مت االشــتباه مبجموعــة مــن ســجناء إصالحيــة احلائــر‬\n   ‫تــدور حولهــم الشــبهات بتعاطــي املخــدرات ومت بعــث املذكــور ملركــز‬\n   ‫صحــي إصالحيــة احلائــر ألخــذ عينــة منــه وإرســالها للتحليــل ‪ .‬وقــد أثبــت‬\n   ‫التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقــب الســموم‬\n   ‫والكيميــاء الطبيــة الشــرعية املرفــق رقــم (‪/9022‬س) لعــام ‪1432‬ه ـ‬\n   ‫إيجابيــة عينــة مســتخلص بــول املذكــور للمــادة الفعالــة للحشــيش وهــو‬\n   ‫مــن املــواد املخــدرة واملدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام‬\n\n                                                                                       ‫‪150‬‬\n\f      ‫مكافحــة املخــدرات واملؤثــرات الصــادر باملرســوم امللكــي رقــم م‪39/‬‬\n      ‫يف ‪1426/7/8‬ه ـ وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام‬\n      ‫إلــى ‪ /‬بتعاطــي احلشــيش املخــدر املجــرم مبوجــب املــادة (الثالثة) من نظام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n      ‫(م‪ )39/‬وتاريــخ ‪1426/07/08‬ه ـ ‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪1 :‬ـ‬\n      ‫مــا تضمنــه محضــر القبــض املنــوه عنــه املرفــق لفــة رقــم (‪2 . )1‬ـ مــا‬\n      ‫تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة رقــم (‪. )2‬‬\n      ‫وببحــث ســوابقه اتضــح وجــود أربــع ســوابق مســجلة عليــه حتــى تاريخــه‬\n      ‫األولــى ســابقة مضاربــة ‪ ،‬والثانيــة ســابقة معاكســة مقترنــة بالتلفــظ‬\n      ‫بألفــاظ غيــر الئقــة ‪ ،‬والثالثــة ســابقة مضاربــة ‪ ،‬والرابعــة ســابقة‬\n      ‫التهديــد مقترنــة بإطــاق نــار وحيــازة ســاح بــدون ترخيــص ‪ ،‬وتبــن‬\n      ‫وجــود قضيــة مخــدرات عليــه برقــم (‪ ).....‬صــدر بهــا القــرار الشــرعي‬\n      ‫رقــم (‪ ).....‬وتاريــخ ‪1427/8/8‬ه ـ ‪ .‬وحيــث إن مــا أقــد عليــه املذكــور‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب إثبــات إدانتــه مبــا‬\n      ‫اســند إليــه واحلكــم عليــه باآلتــي ‪1 :‬ـ إجــراء املقتضــى الشــرعي بحقــه‬\n      ‫وفق ـ ًا للفقــرة ( األولــى ) مــن املــادة (‪ )41‬الواحــدة واألربعــن مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة إليــه لتعاطيــه احلشــيش املخــدر‬\n      ‫‪2 .‬ـ منعــه مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء فتــرة تنفيــذ عقوبــة‬\n      ‫ســجنه وفقـ ًا للفقــرة ( األولــى ) مــن املــادة (‪ )56‬مــن نفــس النظــام املشــار‬\n      ‫إليــه ‪3  .‬ـ تشــديد العقوبــة عليــه لكثــرة ســوابقه اســتناد ًا لبرقيــة ســمو‬\n      ‫نائــب وزيــر الداخليــة رقــم ( ‪ )93958/5/5/1‬وتاريــخ ‪1429/8/23‬ه ـ‬\n      ‫‪ .‬هــذه دعــواي ‪  ،‬وبســؤال املدعــى عليــه أجــاب بقولــه إن مــا ذكــره‬\n      ‫املدعــي العــام غيــر صحيــح فلــم أتعاطــى احلشــيش املخــدر وســوابقي‬\n\n\n‫‪151‬‬\n\f‫صحيحــة هكــذا أجــاب وبطلــب البينــة مــن املدعــي العــام قــال بينتــي‬\n‫مــا يف األوراق وبالرجــوع لــأوراق وجــدت أن التهمــة مبنيــة علــى حتليــل‬\n‫داخــل الســجن وبعــرض ذلــك علــى املدعــى عليــه قــال إننــي محكــوم‬\n‫علــي يف قضيــة أخــرى خمســة عشــر ســنة وقــد أمضيــت ســبع ســنوات‬\n‫وبقــي ثمــان ســنوات وأختلــط بســجناء كثيريــن ورائحــة الســجن تفــوح‬\n‫بــكل شــيء ورمبــا أصابنــي شــي مــن روائــح املــدة الطويلــة هكــذا قــرر‬\n‫كمــا وجــدت أن املدعــى عليــه منكــر بــاألوراق مــا نســب إليــه كمــا‬\n‫وجــدت خطــاب مديــر شــعبة إصالحيــة احلائــر تتضمــن أن املذكــور‬\n‫موقــوف لديهــم يف قضيــة طعــن ودهــس شــخص وصــدر بحقــه القــرار‬\n‫الشــرعي املتضمــن ســجنه ملــدة خمســة عشــر ســنة وجلــده ثالثــة آالف‬\n‫جلــدة فبنــاء علــى مــا تقــدم وحيــث أن هــذه الدعــوى أقيمــت بنــاء علــى‬\n‫حتليــل واملذكــور يختلــط بســجناء آخريــن مــن مــدة طويلــة ولــم يعثــر‬\n‫بحوزتــه علــى شــيء ولــم يشــاهد يتعاطــى شــيء وإمنــا ورود شــبهه فقــط‬\n‫وال يوجــد تقريــر كيمــاوي بذلــك واحلــدود تــدرأ بالشــبهات لــذا لــم يثبــت‬\n‫لــدي إدانــة املدعــى عليــه بشــيء‪ ،‬وصرفــت النظــر عــن مطالبــة املدعــي‬\n‫العــام بحــد املســكر وغيــره وبــه حكمــت وبعــرض احلكــم علــى‬\n‫احملكــوم عليــه قــرر القناعــة أمــا املدعــي العــام فقــد طلــب اســتئنافه‬\n‫مكتفي ـ ًا بالئحــة الدعــوى ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‪1434/05/28‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض  برقــم‬\n‫وتاريــخ ‪1434/6/6‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n\n\n                                                                                   ‫‪152‬‬\n\f        ‫باحملكمــة الشــيخ‪ /‬املســجل برقــم  وتاريــخ ‪1434/5/28‬ه ـ اخلــاص‬\n        ‫بدعــوى املدعــي العــام ضــد ‪ /‬التهامــه بقضيــة مخــدرات علــى النحــو‬\n      ‫املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‪  .‬‬\n        ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n        ‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                ‫وســلم‪.‬‬\n\n\n\n\n‫‪153‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":149,"source_page_end":153,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c3841b1d105b4c4082a40f3f7695b4c2d15de08261211a93427795c61d0eb942","normalized_text_hash":"b0f262d0e312987c3d83474b656e4e9df0c09acdbe94c2625b2a1f33adafed98","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p149-34226530"},{"id":"7b2a521c-b18e-5383-9a11-d9352d6c51c0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلشيش واحلبوب احملظورة إقرار -حد املسكر -التعزير باملنع من السفر -رد دعوى املدعي العام .","document_number":"34263866","case_number":"34302423","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/10","year":"1434","subject":"مخدرات -تعاطي احلشيش واحلبوب احملظورة إقرار -حد املسكر -التعزير باملنع من السفر -رد دعوى املدعي العام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪  34263866:‬تاريخه ‪1434/07/10 :‬هـ‬\n                          ‫رقم الدعوى‪34302423 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34314421‬تاريخه‪1434/09/08 :‬هـ‬\n\n\n\n      ‫مخــدرات ‪ -‬تعاطــي احلشــيش واحلبــوب احملظــورة ـ إقــرار ‪ -‬حــد املســكر‬\n                        ‫‪ -‬التعزيــر باملنــع مــن الســفر ‪ -‬رد دعــوى املدعــي العــام ‪.‬‬\n\n\n\n      ‫‪.1‬ـ قولــه صلــى اهلل عليــه وســلم «مــن شــرب اخلمــر فاجلــدوه» رواه‬\n                                             ‫أحمــد‪ ،‬وأبــو داوود ‪ ،‬والنســائي ‪.‬‬\n      ‫‪.2‬ـ إجمــاع الصحابــة ‪ -‬رضــي اهلل عنهــم ‪ -‬علــى جلــد شــارب اخلمــر‬\n                         ‫ثمانــن جلــدة‪ ( .‬ينظــر ‪ :‬كشــاف القنــاع ‪)99/14‬‬\n      ‫‪.3‬ـ جلــد شــارب اخلمــر ثمانــن هــو املذهــب عنــد احلنابلــة ‪ ،‬وعليــه‬\n                       ‫جماهيــر األصحــاب‪ ( .‬ينظــر ‪ :‬اإلنصــاف ‪.)441/15‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه األول والثانــي بشــرب املســكر‪،‬‬\n      ‫واألول كذلــك بتعاطــي احلشــيش املخــدر‪ ،‬واحلبــوب املنبهــة احملظــورة‪،‬‬\n      ‫طلــب املدعــي العــام إقامــة احلــد عليهمــا لقــاء شــربهما للمســكر وطلــب‬\n      ‫املدعــي العــام بحبــس املدعــى عليــه األول ومنعــه مــن الســفر تطبيقــا‬\n      ‫ألحــكام املــواد أرقــام (‪ )41‬و (‪ )56‬مــن نظــام مكافحــة املخــدرات‪،‬‬\n      ‫حيــث أنــه أثنــاء قيــام نقطــة تفتيــش بأحــد األحيــاء ‪ ،‬مت اســتيقاف‬\n      ‫الســيارة وكانــت بقيــادة املدعــى عليــه األول ومعــه املدعــى عليــه الثاني‪،‬‬\n\n‫‪161‬‬\n\f  ‫أقــر  املدعــى عليــه األول بالدعــوى‪ ،‬وعثــر بجوالــه علــى صــور ســجائر‬\n‫ملفوف وحبوب منبهة ‪ ،‬وباســتجوابهما اعترف  األول بشــرب املســكر  ‬\n  ‫وتعاطــي احلشــيش املخــدر ‪  ،‬واحلبــوب املنبهــة احملظــورة و اعترف  الثاني‬\n  ‫بشــرب املســكر‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بجلــد املدعى‬\n  ‫عليــه األول والثانــي  حــد املســكر و احلكــم بتطبيــق املــادة (‪ )56‬مــن‬\n  ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة بحــق املدعــى عليــه األول‬\n  ‫ومنعــه مــن الســفر‪ ،‬رد دعــوى املدعــي العــام ضــد املدعــى عليــه األول‬\n  ‫بتطبيــق املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n  ‫لعــدم انطباقهــا بحقــه وقنــع املدعــى عليــه األول باحلكــم ‪ ،‬وقنــع املدعــى‬\n  ‫عليــه الثانــي باحلكــم ‪ ،‬واعتــرض املدعــي العــام علــى احلكــم بــدون‬\n                          ‫الئحــة وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                     ‫‪162‬‬\n\f      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا‪ ......‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n      ‫مــن هيئــة التحقيــق واإلدعــاء العــام واملقيــدة لــدى احملكمــة برق ـم  ‬\n        ‫وتاريــخ ‪1434/7/1‬ه ـ واحملالــة لنــا مــن فضيلة رئيــس احملكمة اجلزائية‬\n        ‫بالدمــام برقــم ‪ ......‬وتاريــخ ‪1434/7/1‬ه ـ افتتحــت اجللســة يف يــوم‬\n        ‫االثنــن ‪1434/7/10‬ه ـ الســاعة الثامنــة والنصــف وفيهــا قــدم املدعــي‬\n        ‫العــام دعــواه ونصهــا اآلتــي‪ :‬بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام‬\n        ‫لفــرع املنطقــة الشــرقية أدعــي علــى كل مــن‪ ...... -1 /‬ســعودي اجلنســية‬\n        ‫مبوجــب الســجل املدنــي رقــم‪  ...... -2/‬أردانــي اجلنســية مبوجــب رخصــة‬\n        ‫اإلقامــة رقــم ‪  ......‬حيــث إنــه يف يــوم الســبت ‪1434/6/3‬ه ـ أثنــاء قيــام‬\n        ‫نقطــة تفتيــش بحــي الكورنيــش بالدمــام طريــق امللــك عبــداهلل مت‬\n        ‫اســتيقاف ســيارة مــن نــوع (‪ )......‬حتمــل لوحــة رقــم (‪ )....‬بقيــادة املدعــى‬\n        ‫عليــه  ويرافقــه وقــد اتضــح أن املدعــى عليــه األول عنــد القبــض  بحالــة‬\n      ‫غيــر طبيعيــة وباستشــمامه لوحــظ انبعــاث رائحــة املســكر مــن أنفاســه‬\n      ‫وبتفتيــش جهــازه النقــال عثــر علــى صــور ســجائر ملفــوف وحبــوب منبــه‬\n      ‫محظــورة وباســتجواب األول أقــر بأنــه يشــرب املســكر ويتعاطــى‬\n      ‫احلشــيش املخــدر واحلبــوب املنبهــة واحملظــورة وباســتجواب الثانــي أقــر‬\n      ‫بأنــه يشــرب املســكر وانتهــى التحقيــق التهــام األول بشــرب املســكر‬\n      ‫وتعاطيــه للحشــيش املخــدر واحلبــوب املنبهــة واحملظــورة واتهــام الثانــي‬\n      ‫بشــربه املســكر وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬اعترافهمــا مبــا‬\n      ‫نــوه عنهمــا املــدون مبحضــر اســتجوابهما املرفــق علــى اللفــة رقــم (‪)8-5‬‬\n\n‫‪163‬‬\n\f  ‫‪ -2‬محضــر تنفيــذ املهمــة املنــوه عنــه املرفــق علــى اللفــة رقــم (‪-3 )2‬‬\n  ‫محضــر االستشــمام املنــوه عنــه بحــق املتهــم ‪ ......‬املــدون علــى الصفحــة‬\n  ‫رقــم (‪ )6‬مــن ملــف التحقيــق املرفــق علــى اللفــة رقــم (‪ )1‬وبالبحــث‬\n  ‫عــن ســوابقهما لــم يعثــر لهمــا علــى ســوابق وحيــث إن مــا أقــدم عليــه‬\n  ‫املدعــى عليهمــا املذكــوران وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا‬\n  ‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب اآلتــي‪ :‬أوال‪ :‬إثبــات إدانتهمــا‬\n  ‫بشــرب املســكر واحلكــم عليهمــا بحــد الســكر لقــاء ذلــك‪ .‬ثانيــا‪:‬‬\n  ‫إثبــات إدانــة املدعــى عليــه ‪ ......‬مبــا أســند إليــه مــن تعاطيــه للحشــيش‬\n  ‫املخــدر واحلبــوب املنبهــة واحملظــورة وفقـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم‬\n  ‫(‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه‬\n  ‫مبــا يلــي‪ -1 :‬بعقوبــة الســجن الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n  ‫(‪ )41‬مــن النظــام ‪ -2‬منعــه مــن الســفر وفقـ ًا للفقــرة رقــم (‪ )1‬مــن املــادة‬\n  ‫رقــم (‪ )56‬مــن النظــام هكــذا ادعــى وبعــرض دعــوى املدعــي العــام‬\n  ‫ا مــا ذكــره املدعــي العــام مــن‬    ‫علــى املدعــى عليــه الثانــي أجــاب قائ ـ ً‬\n  ‫شــربي للمســكر فذلــك صحيــح حيــث قــد ســبق وأن شــربته يف دولــة‬\n  ‫ـاء علــى مــا‬\n               ‫البحريــن هكــذا أجــاب وأمــا املدعــى عليــه فلــم يحضــر فبنـ ً‬\n  ‫تقــدم مــن دعــوى املدعــي العــام وإجابــة املدعــى عليــه وإقــراره بالدعــوى‬\n  ‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ولقولــه صلــى اهلل عليــه وســلم (مــن‬\n  ‫شــرب اخلمــر فاجلــدوه) رواه أحمــد وأبــو داود والنســائي كمــا انعقــد‬\n  ‫إجمــاع الصحابــة رضــي اهلل عنهــم علــى جلــد شــارب اخلمــر ثمانــون جلــدة‬\n  ‫(كشــاف القنــاع عــن اإلقنــاع ‪ )99/14‬وهــو املذهــب وعليــه جماهيــر‬\n‫األصحــاب (اإلنصــاف ‪ )441/15‬لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه  ‬\n  ‫بشــرب اخلمــر املســكر وقــررت عقابــه علــى ذلــك باجللــد ثمانــن جلــدة‬\n\n\n                                                                                            ‫‪164‬‬\n\f      ‫دفعــة واحــدة حــد املســكر ويكــون التنفيــذ يف مــكان عــام يحضــره‬\n      ‫جمــع مــن النــاس وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن‬\n      ‫قــرر املدعــى عليــه القناعــة باحلكــم كمــا قــرر املدعــي العــام عــدم‬\n      ‫االعتــراض وجــرى إفهــام املدعــي العــام بأنــه ســوف يتــم نظــر الدعــوى‬\n      ‫بحــق املدعــى عليــه يف حــال حضــوره وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n                                      ‫علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/7/10‬ه ـ‬\n      ‫احلمــدهلل وحــده وبعــد ففــي يــوم االثنــن ‪1434/7/10‬ه ـ حضــر املدعــي‬\n      ‫العــام كمــا حضــر املدعــى عليــه وبعــرض دعــوى املدعــي العــام علــى‬\n      ‫ا مــا ذكــره املدعــي العــام كلــه صحيــح‬   ‫املدعــى عليــه األول أجــاب قائـ ً‬\n      ‫فقــد ســبق وأن تعاطيــت املســكر واحلشــيش املخــدر واحلبــوب احملظــورة‬\n      ‫قبــل عــدة أشــهر وتركتهــا اآلن ولــم يحكــم علــي وال توجــد لدي ســوابق‬\n      ‫هكــذا أجــاب ثــم جــرى الرجــوع إلــى املعاملــة فوجــدت علــى لفــة رقــم‬\n      ‫(‪ )1‬دفتــر التحقيــق ص (‪ )8‬محضــر استشــمام املتضمــن انبعــاث رائحــة‬\n      ‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي‬\n                                               ‫املســكر مــن املدعــى عليــه فبنـ ً‬\n      ‫العــام وإجابــة املدعــى عليــه وإقــراره بالدعــوى وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا وبنــاء علــى الفقــرة (‪ )2‬مــن املــادة (‪ )3‬والفقــرة (‪ )1‬مــن‬\n      ‫املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات املؤثــرات العقلــي وبنــاء‬\n      ‫علــى املــادة (‪ )30‬مــن الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة لــذا فقــد ثبــت لــدي تعاطــي املدعــى عليــه للحشــيش‬\n      ‫املخــدر واحلبــوب احملظــورة وشــربه للمســكر وقــررت عقابــه علــى‬\n      ‫ذلــك باآلتــي‪ :‬أوالً‪ :‬رد مطالبــة املدعــي العــام بتطبيــق الفقــرة (‪ )1‬مــن‬\n      ‫املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات لعــدم انطباقهــا‪ .‬ثانيـاً‪ :‬جلــد‬\n      ‫املدعــى عليــه ثمانــن جلــدة دفعــة واحــدة حــد املســكر ويكــون التنفيــذ‬\n\n\n‫‪165‬‬\n\f‫يف مــكان عــام يحضــره جمــع مــن النــاس لقــاء شــربه احلشــيش املخــدر‬\n‫وشــربه للمســكر‪ .‬ثالثـاً‪ :‬منــع املدعــى عليــه مــن الســفر ملــدة ســنتني تبــدأ‬\n‫مــن تاريــخ احلكــم‪ .‬وبــكل مــا تقــدم حكمــت وبعــرض احلكــم علــى‬\n‫الطرفــن قــرر املدعــى عليــه القناعــة باحلكــم وأمــا املدعــي العــام فقــرر‬\n‫عــدم القناعــة باحلكــم وطلــب االســتئناف بالئحــة يقدمهــا فأفهمتــه بأنه‬\n‫ســوف يجــري بعــد قليــل تســليمه نســخة مــن احلكــم ليقــدم اعتراضــه‬\n‫خــال ثالثــن يوم ـ ًا مــن اآلن يكــون حقــه يف االســتئناف بعــد مضــي‬\n‫هــذه املــدة ســاقط ًا ففهــم ذلــك واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n                                              ‫محمــد‪ .‬حــرر يف ‪1434/07/10‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اخلميــس ‪1434/10/29‬ه ـ افتتحــت‬\n‫اجللســة الســاعة الثامنــة إال ربــع وفيهــا وردتنــا املعاملــة مــن محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية برقــم ‪ 34/2270787‬يف ‪1434/10/8‬ه ـ‬\n‫وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم ‪ ......‬يف‬\n‫‪1434/9/8‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق وصلــى‬\n‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                   ‫‪1434/10/29‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم وتاريــخ ‪1434/9/1‬ه ـ الــواردة مــن فضيلــة رئيــس‬\n‫احملكمة اجلزائية مبدينة الدمام املكلف برقم وتاريخ ‪1434/8/23‬هـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪......‬‬\n‫املســجل برقــم ‪ ......‬وتاريــخ ‪1434/7/10‬ه ـ اخلــاص بدعــوى‪ ......‬املدعــي‬\n‫كل مــن ‪( ...... /2 ...... /1‬أردنــي اجلنســية) يف قضيــة‬       ‫العــام ضــد‪ٍ ......‬‬\n\n                                                                                         ‫‪166‬‬\n\f      ‫خمــور وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n      ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n                                                            ‫حــرر يف ‪1434/9/6‬هــ‪.‬‬\n\n\n\n\n‫‪167‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":161,"source_page_end":167,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"959e92df72f13ade7085726489f5b26cd445f588964b92dd52d5c5e239577965","normalized_text_hash":"1937176e678d87e1aec9604908b96afc50b784bc6bfa761aad14973d199d143b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p161-34263866"},{"id":"7bf2f41c-a052-55f4-b0e6-69f5d297da37","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -تعاطي الهروين املخدر -التستر على مصدر املخدرات -إقرار -إقامة حد املسكر على متعاطي الهروين- التعزير باملنع من السفر.","document_number":"3426950","case_number":"34303614","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/9","year":"1434","subject":"مخدرات -تعاطي مخدرات -تعاطي الهروين املخدر -التستر على مصدر املخدرات -إقرار -إقامة حد املسكر على متعاطي الهروين- التعزير باملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪  3426950 :‬تاريخه ‪1434/07/9 :‬هـ‬\n                   ‫رقم الدعوى‪34303614 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n    ‫تاريخه‪1434/8/1 :‬هـ‬         ‫‪34284262‬‬\n\n\n\n‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬تعاطــي الهرويــن املخــدر ‪ -‬التســتر علــى‬\n‫مصــدر املخــدرات ‪ -‬إقــرار ‪ -‬إقامــة حــد املســكر علــى متعاطــي الهرويــن‪-‬‬\n                                               ‫التعزيــر باملنــع مــن الســفر‪.‬‬\n\n\n\n\n            ‫‪-1‬قول النبي صلى اهلل عليه وسلم ‪ ( :‬كل مسكر حرام ) ‪.‬‬\n                                   ‫‪-2‬قاعدة ( املرء مؤاخذ بإقراره ) ‪.‬‬\n          ‫‪-3‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه بتعاطــي الهرويــن املخــدر‪،‬‬\n‫وتســتره علــى مصــدر املخــدرات‪ ،‬وطلــب املدعــي العــام تعزيــر املدعــى‬\n‫عليــه بالســجن واملنــع مــن الســفر وتطبيــق املــواد (‪ ) 56/ 41‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة بحقــه واملــادة رقــم ‪ 30‬مــن‬\n‫الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫وتعزيــره لقــاء تســتره علــى مصــدر هــذه املخــدرات ‪ ،‬أقــر املدعــى عليــه‬\n‫بتعاطــي الهيرويــن املخــدر أثنــاء التحقيــق معــه يف قضيــة قتــل وأقــر‬\n‫املدعــى عليــه أنــه قــام بإخبــار اجلهــة األمنيــة مبصــدر املخــدرات وأنكــر‬\n‫التســتر وطلــب القاضــي مــن املدعــي العــام البينــة علــى تســتر املدعــى‬\n\n                                                                                    ‫‪168‬‬\n\f      ‫عليــه علــى مصــدر املخــدرات‪  ،‬فقــرر بأنــه ليــس لديــه ســوى مــا جــاء يف‬\n      ‫طيــات املعاملــة‪  ،‬وبتصفحهــا لــم يجــد القاضــي بينــة علــى تســتر املدعــى‬\n      ‫عليــه علــى مصــدر املخــدرات بنــاء علــى مــا تقــدم حكمــت احملكمــة‬\n      ‫علــى املدعــى عليــه بحــد املســكر‪ ،‬والتعزيــر باملنــع مــن الســفر ورد‬\n      ‫دعــوى املدعــي العــام ضــد املدعــى عليــه حيــال مــا جــاء يف طلبــه تطبيــق‬\n      ‫املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة بحــق‬\n      ‫املدعــى عليــه‪ ،‬قــرر املدعــي العــام االعتــراض بالئحــة ‪  ،‬وأمــا املدعــى‬\n      ‫عليــه فقــد قنــع باحلكــم ‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n        ‫اجلزائيــة‬\n           ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة‬\n        ‫باالحســاء  وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة  رئيــس احملكمــة‬\n      ‫اجلزائيــة يف محافظــة االحســاء املكلــف برقــم  وتاريــخ ‪1434/07/02‬هـ  ‬\n        ‫املقيــدة باحملكمــة برقــم وتاريــخ ‪1434/07/02‬هــ  ففــي يــوم  األحــد‬\n        ‫املوافق ‪1434/07/09‬هـ افتتحت اجللســة الســاعة ‪ 09 : 45‬وفيها حضر‬\n        ‫املدعــي العــام وادعــى ضــد احلاضــر معــه  ‪ ......‬ســعودي اجلنســية مبوجــب‬\n        ‫الســجل املدنــي رقــم ‪  ......‬قائــا يف دعــواه باإلطــاع علــى خطــاب مديــر‬\n        ‫شــرطة محافظة األحســاء رقم (‪9/21‬ق‪ )7286/‬وتاريخ‪1433/8/10‬هـ‬\n        ‫املتضمــن إحالــة األوراق املفــرزة مــن ملــف التحقيــق مــع املدعــى عليــه‬\n        ‫يف قضيــة قتــل ملــا تضمنــه التحقيــق مــن إقــرار املدعــى عليــه بتعاطيــه‬\n        ‫للهرويــن املخــدر وإحالــة األوراق إلــى مكافحــة املخــدرات بحكــم‬\n        ‫االختصــاص وبتاريخ‪1434/6/4‬ه ـ وبنــاء علــى أمــر مــن مديــر العمليــات‬\n        ‫مبكافحــة املخــدرات املبنــي علــى خطــاب مديــر القضايــا واملوقوفــن‬\n\n‫‪169‬‬\n\f‫رقــم (‪ )309‬وتاريخ‪1434/5/20‬ه ـ املتضمــن طلــب البحــث والقبــض‬\n‫علــى املدعــى عليــه والــذي اتضــح بأنــه يعمــل ســكرتي مبستشــفى‬\n‫وبالتنســيق مــع الرئيــس املباشــر أفــاد بــأن املدعــى عليــه يتواجــد مبركز‬\n‫طــب األســنان وســوف يقــوم بإرشــاد الفرقــة إليــه ‪ ،‬ويف متــام الســاعة‬\n‫العاشــرة صباح ـ ًا مت القبــض علــى املدعــى عليــه وباســتجواب املدعــى‬\n‫عليــه أقــر بتعاطيــه للهيرويــن املخــدر قبــل القبــض عليــه بثالثــة أســابيع‬\n‫وشــرائها مــن شــخص يف مدينــة اخلبــر ال يعرفــه وانتهــى التحقيــق معــه‬\n‫إلــى توجيــه االتهــام لــه بتعاطــي الهيرويــن املخــدر املجــرم مبوجــب املــادة‬\n‫(الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى‬\n‫مصــدر املخــدرات وذلــك لألدلــة والقرائــن التاليــة ‪1 :‬ـ مــا جــاء يف إقــراره‬\n‫املنــوه عنــه واملــدون علــى الصفحــات رقــم (‪ )5،4،3‬مــن دفتــر االســتدالل‬\n‫لفــة رقــم (‪2 )13‬ـ مــا جــاء يف خطــاب مديــر شــرطة محافظــة األحســاء‬\n‫املرفــق لفــة رقــم (‪ )6‬وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل‬\n‫أهليتــه املعتبــرة شــرع ًا فعــل مجــرم ومعاقــب علي ــه نظام ـ ًا لــذا أطلــب‬\n                             ‫إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n‫‪-1‬العقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن النظــام املشــار‬\n              ‫إليــه واملــادة (‪ )30‬مــن الالئحــة التنفيذيــة لقــاء مــا أســند إليــه‬\n‫‪2‬ـ بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام مبنعــه‬\n                                              ‫مــن الســفر بعــد تنفيــذ محكوميتــه‬\n         ‫‪3‬ـ عقوبة تعزيرية لقاء تستره على مصدر املخدرات هذه دعواي ‪.‬‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n‫العــام مــن أننــي اســتخدمت الهيرويــن املخــدر وكان ذلــك قبــل القبــض‬\n\n\n                                                                                           ‫‪170‬‬\n\f      ‫علــي بثالثــة أســابيع فهــذا كلــه صحيــح وأنــا تائــب ونــادم وأمــا ما ذكره‬\n      ‫املدعــي العــام مــن تســتري علــى مصــدره فغيــر صحيــح حيــث إننــي‬\n      ‫أخبرتهــم بأنــي أحتصــل عليهــا مــن شــخص باكســتاني يف اخلبــر عــن‬\n      ‫طريــق بطاقــات ‪ .....‬هكــذا أجــاب وبســؤال املدعــي العــام هــل لديــه بينــة‬\n      ‫علــى تســتر املدعــى عليــه علــى مصــدر املخــدرات أجــاب قائــا بينتــي مــا‬\n      ‫ذكرتــه يف أوراق املعاملــة هكــذا أجــاب وباإلطــاع علــى املعاملــة وجــد‬\n      ‫أن أقــوال املدعــى عليــه يف دفتــر التحقيــق مطابقــة ملــا ذكــره يف جوابــه‬\n      ‫يف مجلــس احلكــم فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإقــرار‬\n      ‫املدعــى عليــه وحيــث إن املــرء مؤاخــذ بإقــراره وحيــث إن املدعــى عليــه‬\n      ‫أنكــر تســتره علــى مصــدر الهيرويــن واملدعــي العام لم يحضــر بينة على‬\n      ‫ذلــك ولقــول النبــي صلــى اهلل عليــه وســلم كل مســكر حــرام وحيــث إن‬\n      ‫الهيرويــن يشــترك مــع اخلمــر يف منــاط احلكــم فيأخــذ حكمــه لذلــك‬\n      ‫كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه بتعاطــي الهيرويــن املخــدر ولــم‬\n      ‫يثبــت لــدي تســتره علــى مصــدره وحكمــت مبــا يلــي ‪ :‬أو ًال ـ جلــد املدعــى‬\n      ‫عليــه ثمانــون جلــده حــد املســكر دفعــه واحــدة ثانيـ ًا ـ منــع املدعــى عليــه‬\n      ‫من الســفر خارج اململكة مدة ســنتني بعد تنفيذ مدة محكوميته ثالث ًا‬\n      ‫ـ رد دعــوى املدعــي العــام بخصــوص معاقبــة املدعــى عليــه مبوجــب املــادة‬\n      ‫‪ 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وعلــى تســتره لعــد‬\n      ‫ثبوتهــا وبــه حكمــت وبعــرض ذلــك علــى املدعــى عليــه و املدعــي العــام‬\n      ‫قــرر املدعــى عليــه قناعتــه بــه بينمــا قــرر املدعــي العــام عــدم قناعتــه‬\n      ‫وطلــب االســتئناف فأجبتــه لطلبــه وقــرر بأنــه لــن يقــدم الئحــة اعتراضيــة‬\n      ‫وإمنــا يكتفــي بــأوراق املعاملــة والئحــة الدعــوى وختمــت اجللســة يف متــام‬\n      ‫الســاعة ‪ 10 : 15‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n‫‪171‬‬\n\f                                    ‫وصحبــه وســلم ‪ .‬حــرر يف  ‪ 1434/07/09‬ه ـ‬\n  ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n  ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n  ‫مــن فضيلــة  القائــم بعمــل رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء‬\n  ‫املكلــف برقــم ‪ ......‬وتاريــخ ‪1434/7/12‬ه ـ املقيــدة لــدى احملكمــة‬\n  ‫برقــم وتاريــخ ‪1434/7/16‬هــ  املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ املســجل برقــم   وتاريــخ ‪1434/7/9‬هــ  ‬\n  ‫اخلــاص بدعــوى‪ ......‬املدعــي العــام ضــد‪ ......‬املدعــى عليــه يف قضيــة‬\n  ‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n  ‫فيــه ‪ .‬وبدراســة  القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n  ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                   ‫وســلم حرريف‪1434/7/30‬ه ـ ‪.‬‬\n\n\n